"use strict";(globalThis.webpackChunkgrc||=[]).push([[45],{66730(e){e.exports=JSON.parse('[{"citeKey":"fernandes2026gpuh5","slug":"fernandes-2026-gpuh5-9b21","title":"GPUH5: A GPU-first I/O Library for Scientific Data","authors":["J. Fernandes","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"I/O is a bottleneck in GPU-accelerated science, yet scientific data-format libraries run only on the host. A kernel cannot write where its data lives: it must exit and copy its array before HDF5 can run, so the write point becomes a kernel boundary. Systems that let a GPU initiate I/O give up the data model, emitting flat, untyped byte ranges. We present GPUH5, a GPU-first I/O library for persistent kernels. It keeps HDF5\'s hierarchical paths and chunked arrays, replacing the container format with a key-value store, so the host precomputes every chunk\'s key and an in-kernel write reduces to enqueuing a pointer, light enough that the producer holds 98.8% achieved occupancy. On a single-GPU Gray-Scott simulation writing 380 snapshots to NVMe, GPUH5 hides 96% of the I/O its synchronous twin exposes, finishing 1.9\xd7 faster than default HDF5.","hasAbstract":true,"lede":"We present GPUH5, a GPU-first I/O library for persistent kernels.","links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdsw111&sess=sess129"},"tags":["GPU I/O","HDF5","Scientific Data"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"yildirim2026gdsight","slug":"yildirim-2026-gdsight-4e6a","title":"GDSight: Per-Operation Cross-Layer Attribution for GPUDirect Storage","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"GPUDirect Storage (GDS) copies NVMe data into GPU memory, bypassing the CPU data path and the identity linking an operation to the device work it causes. To our knowledge, no external GDS tool attributes a device command to its causing application operation: cuFile stops at the call, counters report only aggregates, and time-based matching fails once submission is asynchronous, even at one operation in flight. We present GDSight, which attributes each NVMe command to the operation that caused it, whether it entered cuFile or fell back to POSIX. Using eBPF, it matches commands by timing and by physical address, and only address survives asynchrony. On unmodified KvikIO, NIXL and HDF5 we pin pathologies to their cause: a silent bypass cuFile\'s counters miss, 4\xd7 device amplification, and 22\xd7 tail inflation. We show that each diagnosis resolves to a measured intervention, worth up to 17\xd7 where throughput is the limit, or none.","hasAbstract":true,"lede":"We present GDSight, which attributes each NVMe command to the operation that caused it, whether it entered cuFile or fell back to POSIX.","links":{"code":"https://github.com/izzet/gdsight","artifact":"https://doi.org/10.5281/zenodo.22718932","program":"https://sc26.conference-program.com/presentation/?id=ws_pdsw125&sess=sess129"},"tags":["GPUDirect Storage","cuFile","NVMe","eBPF","Cross-Layer I/O Tracing","Per-Operation Attribution","Explainability"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"yildirim2026stageonce","slug":"yildirim-2026-stageonce-6b8e","title":"StageOnce: Speculative Cross-Job Data Staging for LLM Agent Fleets","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific workflows increasingly run as fleets of LLM agents analysing immutable datasets. On a shared compute node, independent staging repeats source reads and creates storage contention, while each job discovers its inputs during reasoning. StageOnce coordinates these speculative path predictions through a node-local daemon, coalescing concurrent misses into one immutable copy while preserving dataset versions and private outputs. Tools read staged inputs directly from the filesystem, without per-read coordination. Recorded-session replays in genomics and astronomy on SSD and HDD backends reduce fleet makespan by 31-51% at 12 concurrent jobs against independent staging. Logical staging remains one copy across every tested fleet size. An ablation isolates speculation, which reduces makespan by 8-49% against reactive shared caching. StageOnce beats independent staging when fleet demand exceeds what reasoning windows can hide and reuse amortises coordination overhead, while smaller working sets can make direct reads or prologue bulk copies preferable.","hasAbstract":true,"lede":"StageOnce coordinates these speculative path predictions through a node-local daemon.","links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost305&sess=sess313"},"tags":["LLM Agents","Data Staging","Speculative Execution","HPC I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"yildirim2026toolfuse","slug":"yildirim-2026-toolfuse-4a7d","title":"ToolFuse: Provenance-Aware In-Flight Coalescing of Redundant Agent Tool Calls","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific workflows increasingly run as fleets of LLM agents analysing immutable datasets. Independent agents can issue equivalent expensive read-only tool calls simultaneously, before a completed-result cache has anything to reuse. ToolFuse addresses this cold-wave gap by coalescing active calls at a gateway between agents and tool handlers. Its contribution is a provenance-aware execution identity that establishes equivalence from versioned dependencies and execution context, rather than arguments alone. Under contention on an exclusive HPC node, 16 equivalent requests become one execution, reducing CPU time by 11.79x and makespan by 2.36x. Peak memory growth falls from 6.44 GiB to 0.53 GiB. Trace replay shows that sharing depends on call duration and arrival timing. For cheap calls, coalescing remains inactive with negligible overhead. ToolFuse admits only calls declared read-only, idempotent, deterministic, and closed-world, and prefers false misses over unsafe sharing.","hasAbstract":true,"lede":"ToolFuse addresses this cold-wave gap by coalescing active calls at a gateway between agents and tool handlers.","links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost306&sess=sess313"},"tags":["LLM Agents","Tool Calls","In-Flight Coalescing","Provenance"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026vigil","slug":"xu-2026-trigger-render-reason-multimodal-llm-agents-c360","title":"Trigger, Render, Reason: Multimodal LLM Agents for Science-Aware Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Gainaru","S. Klasky","A. Kougkas","X.-H. Sun"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Conference","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"abstract":"Scientific simulations on leadership-class HPC systems routinely waste millions of core-hours producing invalid results, yet no tool monitors whether a running simulation computes valid science. We call this blind spot dark waste: simulations that run to completion while computing the wrong answer. We present Vigil, which couples deterministic science-aware triggers with multimodal LLM confirmation through a trigger-render-reason pipeline. Vigil instruments simulations with lightweight checks on derived-quantity operators and regions of interest; when a check detects a potential anomaly, the flagged data is rendered and analyzed by a multimodal model to assess scientific validity. Upon confirming invalid behavior, Vigil can terminate or restart the simulation from a checkpoint, preventing further expenditure on dark waste. We evaluate Vigil across four codes spanning numerical instability, pattern dynamics, turbulence dissipation, and molecular-dynamics failures. Vigil detects every deliberately configured failure with zero false positives and supplies an actionable semantic verdict for each alert.","hasAbstract":true,"lede":"We present Vigil, which couples deterministic science-aware triggers with multimodal LLM confirmation through a trigger-render-reason pipeline.","links":{"program":"https://sc26.conference-program.com/presentation/?id=pap1039&sess=sess236"},"tags":["Coeus","IOWarp"],"_projectIds":["iowarp","coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026triggergated","slug":"xu-2026-trigger-gated-multimodal-1a84","title":"Trigger-Gated Multimodal LLM Agents for In-situ Scientific Simulation Monitoring","authors":["H. Xu","J. Cernuda","A. Kougkas","A. Gainaru","S. Klasky","X.-H. Sun","J. Lofstead"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"WIP","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdswwip113&sess=sess129"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"teves2026typesafe","slug":"teves-2026-type-safe-metadata-d6f0","title":"Type-Safe, Dynamically Defined Metadata Support for Scientific Applications","authors":["J. Teves","C. Brinker","A. Kougkas","A. Gainaru","S. Klasky","X.-H. Sun","J. Lofstead"],"venue":"11th International Parallel Data Systems Workshop (PDSW 2026), held in conjunction with SC26","type":"WIP","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_pdswwip105&sess=sess129"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"rajesh2026explainability","slug":"rajesh-2026-io-observability-explainability-2bb9","title":"Extending I/O Observability to Explainability for Targeted Optimization","authors":["N. Rajesh","S. Neuwirth","J. Lofstead","A. Kougkas","X.-H. Sun","N. Dryden","H. Devarajan"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost229&sess=sess313"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"pawar2026gnnpress","slug":"pawar-2026-gnns-beyond-hbm-3f56","title":"GNNs Beyond HBM: Compressed, Bit-Exact Feature Streaming for Out-of-Core Training","authors":["R. Pawar","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost258&sess=sess313"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"xu2026derivedquantity","slug":"xu-2026-rich-io-centric-derived-quantity-8c30","title":"Rich I/O-centric Derived Quantity Operators for Advanced In Situ Processing","authors":["H. Xu","J. Cernuda","A. Kougkas","X.-H. Sun","A. Gainaru","S. Klasky","M. Taufer","N. Tan","K. Assogba","M. Rafique","B. Nicolae","J. Teves","C. Brinker","L. Pouchard","J. Lofstead"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations. Although performing analysis directly as data is produced (in situ) can mitigate this problem, embedding such analysis routines into complex scientific codes is often impractical or inflexible. We address this by introducing derived quantity operators that provide a modular and pluggable framework within high-level I/O libraries, enabling sophisticated in situ analysis to be performed transparently during data output with minimal modifications to the host application. The operators bind to persistent hierarchical storage through operator-declared metadata, allowing cross-timestep and cross-run analysis to be carried out seamlessly within the I/O path. We demonstrate the capabilities of our operators by integrating correctness validation and important scientific metrics, traditionally executed after simulation runs, directly into the I/O pathway as derived quantities. Our implementation illustrates how complex, non-mathematical analyses such as runtime validation can be efficiently performed during simulation, enabling early detection of errors. Our work broadens the range of in situ analyses achievable through derived quantity operators, promoting more flexible, intelligent, and reliable scientific workflows.","hasAbstract":true,"lede":"Scientific simulations produce increasingly large datasets that surpass practical limits for frequent input and output operations.","links":{"pdf":"https://grc.iit.edu/papers/2026/xu-2026-rich-io-centric-derived-quantity-8c30.pdf"},"tags":["IOWarp","Coeus"],"_projectIds":["iowarp","coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"yildirim2026agentstage","slug":"yildirim-2026-agentstage-7c4a","title":"AgentStage: Exploiting LLM Thinking for Data Staging in Scientific Agents","authors":["I. Yildirim","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents on scientific data tasks spend most of their session wall time inside tool calls reading data from storage. Yet before each tool call, the agent reasons in a thinking phase, during which the storage layer sits idle and the next tool\'s files begin to surface in the reasoning. Exploiting this is hard: the agent rarely names complete paths, so those files must be inferred and then staged before the tool fires. We present AgentStage, which reads the streaming reasoning and the agent\'s filesystem probes to identify those files, then stages them into fast local storage with in-flight decompression so the tool\'s reads land hot. We evaluate AgentStage on three curated I/O-bearing scientific tasks and one data-intensive task from each of three community benchmarks (MLE-bench, KramaBench, DSBench), across four reasoning models (three closed-weight, one open-weight). Under a paired trajectory-replay protocol that fixes each agent\'s tool sequence and varies only cold versus staged execution, AgentStage delivers an average 1.74\xd7 end-to-end speedup on the curated tasks, up to 2.34\xd7 per run. On the three community benchmarks, AgentStage delivers up to 1.36\xd7 speedup. The results show that thinking-phase staging helps when I/O share is high and prefetch completes within the thinking window, while compute-bound or many-file workloads see smaller gains. We show both conditions can be estimated before any staging run, so AgentStage\'s benefit is predictable in advance. AgentStage adds negligible LLM-side overhead and needs no per-model or per-task tuning.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/yildirim-2026-agentstage-7c4a.pdf"},"tags":["LLM Agents","LLM Thinking","Scientific Tasks","Data Staging","Prefetch","HPC I/O","Tiered Storage"],"_projectIds":["iowarp"],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2026acropolis","slug":"pawar-2026-acropolis-1f2a","title":"Acropolis: A Portable, AI-Driven Semantic Search System for HPC","authors":["R. Pawar","L. Logan","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"LLM agents are now a primary interface to data repositories, but they locate files by issuing speculative regex queries through glob, grep, and file reads, creating a guess-and-check loop that is expensive in tool calls and tokens and ignores metadata embedded in scientific file formats. We present Acropolis, a semantic search system that augments a tiered filesystem with adaptive-depth content indexing and exposes it to agents through a typed natural-language interface. Acropolis provides a transparent file-summary operator in the I/O ingest path with content-addressable idempotency, a pluggable search-backend abstraction for lexical, vector, and graph engines, and an MCP server for compatible agents. On a 70-query CMIP6 retrieval benchmark, an agent using Acropolis matches the shell-tool baseline on retrieval accuracy while substantially reducing tool and backend calls per query and LLM token consumption.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2026/pawar-2026-acropolis-1f2a.pdf"},"tags":["Semantic Search","LLM Agents","HPC","Model Context Protocol"],"_projectIds":["iowarp","labios"],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2026aes","slug":"bateman-2026-agent-error-simulator-3c7d","title":"Agent Error Simulator: Fault Injection for Testing Recovery in Agentic Workflows","authors":["K. Bateman","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"22nd IEEE International Conference on eScience (eScience 2026)","type":"Conference","entryType":"inproceedings","date":"September, 2026","year":2026,"era":"iit","month":9,"abstract":"Multi-agent large language model (LLM) workflows are increasingly deployed for complex, multi-step computational tasks. Yet the fault tolerance of these systems (how individual agents respond to malformed inputs, tool failures, and subtle numerical errors) remains poorly characterized. We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection. AES intercepts agent-to-model HTTP traffic via a transparent proxy, injecting three categories of faults (format, logic, and tool call) at configurable points in a hierarchical planner-worker-aggregator workflow. We evaluate four models spanning 2B\u201332B parameters (Qwen2.5-Coder 32B, Gemma4 27B, Mistral 7B, and Granite4 2B) across 194 jobs organized into 10 test groups covering baseline behavior, multi-error injection, workflow scale, context pressure, compaction, and detection timing. Our results reveal a model-size-dependent logic error recovery threshold between 7B and 27B parameters; universal catastrophic failure under aggregator-level logic injection; and model-specific aggregator arithmetic deficits that interact with injected faults in non-obvious ways. We release the benchmark suite, injection tooling, and result data to support reproducible multi-agent fault tolerance research.","hasAbstract":true,"lede":"We present the Agent Error Simulator (AES), a benchmark framework that evaluates LLM agent fault tolerance through controlled, declarative fault injection.","links":{"pdf":"https://grc.iit.edu/papers/2026/bateman-2026-agent-error-simulator-3c7d.pdf"},"tags":["LLM Agents","Fault Injection","Resilience","Multi-Agent Workflows"],"_projectIds":["dtio"],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2320345","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"ye2026pkas","slug":"ye-2026-pkas-predictive-kvcache-aware-scheduling-for-81cf","title":"PKAS: Predictive KVCache-Aware Scheduling for Faster LLM and Transformer Inferences","authors":["J. Ye","A. Maurya","K. Chitty-Venkata","B. Nicolae","A. Kougkas","X.-H. Sun"],"venue":"35th International Symposium on High-Performance Parallel and Distributed Computing (HPDC 2026)","type":"Conference","entryType":"inproceedings","date":"July, 2026","year":2026,"era":"iit","month":7,"doi":"10.1145/3806645.3807819","abstract":"With rising popularity of LLMs, the performance, scalability, and resource-efficiency of inferences become a crucial challenge. The core part of the inference process is the KV cache, which avoids recomputing intermediate attention states, and the batching strategy that batches multiple requests per forward pass to leverage GPU parallelism. KV cache memory grows linearly with sequence length and batch sizes, easily exceeding the limited GPU memory capacity. State-of-the-art inference runtimes use continuous batching to maximize GPU utilization by interleaving the processing of new requests (i.e., prefill requests) with ongoing generation requests (i.e., decode requests). However, existing schedulers greedily admit prefill requests without considering the future KV cache memory required to successfully run the decode phases. This shortsighted approach causes frequent KV cache overflows, which in turn trigger preemption and recomputation of requests, severely degrading both throughput and latency. We propose PKAS, a Predictive KV Cache-Aware Scheduling algorithm to mitigate this inefficiency by reducing preemptions. PKAS uses a low-overhead technique to simulate future KV cache utilization and guide the admissibility for new request candidates. Combined with lightweight output-length predictions, PKAS can make better batching decisions, preventing KV cache overflows and drastically reducing preemptions. Evaluations on diverse models and workloads show that PKAS achieves up to 7.34x higher throughput and 8x lower latency compared to state-of-the-art scheduling, with the largest gains on long-context workloads where KV cache pressure is high.","hasAbstract":true,"lede":"We propose PKAS, a Predictive KV Cache-Aware Scheduling algorithm to mitigate this inefficiency by reducing preemptions.","pages":"402\u2013414","links":{"pdf":"https://grc.iit.edu/papers/2026/ye-2026-pkas-predictive-kvcache-aware-scheduling-for-81cf.pdf","bibtex":"https://grc.iit.edu/papers/2026/ye-2026-pkas-predictive-kvcache-aware-scheduling-for-81cf-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/ye-2026-pkas-predictive-kvcache-aware-scheduling-for-81cf-citation.txt"},"tags":["KV Cache Management","LLM Inference Serving","Scheduling"],"_projectIds":["deepio"],"_funding":[{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"NSF","award":"OAC-2514056","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"chowdhury2026prerope","slug":"chowdhury-2026-pre-vs-post-rope-1e2b","title":"Pre-RoPE versus Post-RoPE: Trading Per-Step Compute for KVCache Survivability","authors":["Z. Chowdhury","J. Cernuda","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Chowdhury_Zia%20Uddin_Pre-RoPE%20versus%20Post-RoPE%20-%20Zia%20Uddin%20Chowdhury.pdf","bibtex":"https://grc.iit.edu/papers/2026/chowdhury-2026-pre-vs-post-rope-1e2b-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/chowdhury-2026-pre-vs-post-rope-1e2b-citation.txt"},"tags":["LLM","KV Cache","RoPE","ML"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"islam2026agenticsearch","slug":"islam-2026-agentic-search-9f3c","title":"Agentic Search Efficiency for Scientific Data Discovery","authors":["S. Islam","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2026/islam-2026-agentic-search-9f3c-poster.pdf","bibtex":"https://grc.iit.edu/papers/2026/islam-2026-agentic-search-9f3c-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/islam-2026-agentic-search-9f3c-citation.txt"},"tags":["AI","LLM","MCP","HPC"],"_projectIds":["iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"tang2026dataflow","slug":"tang-2026-dataflow-workflow-b4e1","title":"Characterizing Dataflow for I/O-Aware Scheduling in HPC Workflows","authors":["M. Tang","L. Guo","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"40th IEEE International Parallel and Distributed Processing Symposium (IPDPS 2026)","type":"Conference","entryType":"inproceedings","date":"May, 2026","year":2026,"era":"iit","month":5,"doi":"10.1109/IPDPS65963.2026.00076","abstract":"Scientific discoveries are increasingly facilitated by data-driven workflows executed in HPC environments, where complex task-to-data exchange patterns cause bottlenecks in shared storage. Existing I/O-aware scheduling techniques use application-oriented metrics that primarily focus on individual task characteristics, leaving workflow-level dataflow behaviors\u2014such as file reuse and producer\u2013consumer I/O patterns\u2014underexplored despite their importance for effective orchestration. This paper presents a workflow-centric methodology to characterize and analyze I/O using workflow-specific patterns and metrics. By correlating workflow structures (e.g., task composition, execution order, and producer\u2013consumer relationships) with I/O metrics (e.g., access type, operation count, and data size), we gain deeper insight into workflow I/O dynamics. We evaluate our approach on six diverse HPC workflows, covering 3,500 task instances and 1,387 unique files, with a total I/O volume of 1.5 TB. This analysis uncovers a spectrum of behaviors related to file reuse, data exchange, and task-level I/O heterogeneity. These insights reveal new opportunities and research directions for I/O-aware scheduling, supporting smarter task placement, data movement, and storage selection in HPC.","hasAbstract":true,"lede":"This paper presents a workflow-centric methodology to characterize and analyze I/O using workflow-specific patterns and metrics.","pages":"868\u2013884","links":{"pdf":"https://grc.iit.edu/papers/2026/tang-2026-dataflow-workflow-b4e1.pdf","bibtex":"https://grc.iit.edu/papers/2026/tang-2026-dataflow-workflow-b4e1-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/tang-2026-dataflow-workflow-b4e1-citation.txt"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2026storagemismatches","slug":"tang-2026-storage-mismatches-7f3d","title":"The Hidden Cost of Storage Mismatches: Why Faster I/O Per Task Can Slow Down Entire Workflows","authors":["M. Tang","L. Guo","N. R. Tallent","A. Kougkas","X.-H. Sun"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"abstract":"Data-intensive scientific workflows in high-performance computing exchange intermediate data between pipeline stages through shared storage such as parallel file systems, local SSDs, and burst buffers. Existing workflow schedulers select storage to maximize individual task throughput, implicitly assuming that faster I/O per task yields faster end-to-end execution. We show this assumption is wrong. We present an empirical study across two scientific workflows\u2014genomics and climate tracking\u2014on a production HPC cluster. By benchmarking storage systems across operation types, transfer sizes, parallelism levels, and data volumes, we uncover two non-obvious findings. First, data movement between storage tiers scales fundamentally differently from read and write operations: copy throughput plateaus or degrades at parallelism levels where reads and writes continue to scale, making cross-tier staging costs unpredictable from standard I/O benchmarks. Second, producer-consumer task pairs can exhibit performance inversion\u2014configurations that maximize throughput for individual tasks introduce costly inter-stage data movement that increases total workflow time by up to 6.8x compared to storage-aware alternatives. Across both workflows, I/O accounts for 42\u201398% of total execution time, yet the penalty from storage mismatches between dependent tasks can exceed the compute cost of the tasks themselves. These patterns hold across fundamentally different access profiles, from large sequential transfers to metadata-heavy many-small-file workloads. Our results demonstrate that producer-consumer data dependencies must be treated as first-class constraints in workflow scheduling.","hasAbstract":true,"lede":"We present an empirical study across two scientific workflows, genomics and climate tracking, on a production HPC cluster.","links":{"poster":"https://grc.iit.edu/papers/2026/tang-2026-storage-mismatches-7f3d-poster.pdf","bibtex":"https://grc.iit.edu/papers/2026/tang-2026-storage-mismatches-7f3d-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/tang-2026-storage-mismatches-7f3d-citation.txt"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"ye2026speculativedispatch","slug":"ye-2026-accelerating-multi-agent-orchestration-with-speculative-539c","title":"Accelerating Multi-Agent Orchestration with Speculative Dispatching","authors":["J. Ye","S. Islam","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"abstract":"Scientific computing workflows are increasingly being restructured around autonomous AI agents. These agents coordinate complex tasks across heterogeneous tools and infrastructure, ranging from molecular simulations spanning quantum chemistry solvers and machine learning potentials to cross-facility manufacturing experiments orchestrated by multi-agent teams. However, existing orchestration approaches either follow static execution graphs defined at design time or delegate routing to an LLM that greedily selects the next agent at each step, without considering resource availability, heterogeneous model and provider selection, and infrastructure constraints. Achieving resource-aware, dynamic, and deterministic orchestration that reasons about task decomposition, agent capabilities, and infrastructure state demands complex planning and dispatching decisions at runtime. This may introduce significant latency before any agent can begin execution. We propose a speculative dispatch mechanism to accelerate multi-agent orchestration. We are the first to apply speculative execution to the dispatch decision. Specifically, our approach speculatively dispatches agents ahead of time while the full orchestration decision is being computed. Since speculative dispatch can mispredict, a reconciliation engine reconciles the speculative and optimal dispatch plans. Unlike single-agent speculation approaches that accept or discard results entirely, our framework commits correct work, salvages partial matches, and flushes mispredictions, reducing the cost of misprediction. As workload patterns evolve over time, a learner progressively refines speculation accuracy from reconciliation outcomes, enabling the system to improve dispatch predictions. Preliminary results show speculative planner produces partially correct dispatch plans (0.50-0.78 similarity) at 4-10x lower latency than optimal planner, confirming the latency-quality gap speculative dispatch exploits.","hasAbstract":true,"lede":"We propose a speculative dispatch mechanism to accelerate multi-agent orchestration.","links":{"poster":"https://grc.iit.edu/papers/2026/ye-2026-accelerating-multi-agent-orchestration-with-speculative-539c-poster.pdf","bibtex":"https://grc.iit.edu/papers/2026/ye-2026-accelerating-multi-agent-orchestration-with-speculative-539c-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/ye-2026-accelerating-multi-agent-orchestration-with-speculative-539c-citation.txt"},"tags":["IOWarp","Multi-Agents","Speculative Dispatching"],"_projectIds":["iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"yildirim2026ioefficient","slug":"yildirim-2026-correct-is-not-io-efficient-9d2f","title":"Correct Is Not I/O Efficient: Characterizing I/O Behavior of LLM Agents on Scientific Data","authors":["I. Yildirim","J. Ye","J. Cernuda","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"abstract":"LLM coding agents are increasingly used to generate scientific workflows, but evaluations stop at output correctness. For data-intensive science, this is incomplete: two workflows can produce the same valid result while placing different pressure on storage systems. We study I/O behavior in correctness-passing LLM-generated scientific workflows. Contributions: a benchmark of scientific data tasks paired with expert implementations and a containerized execution harness; POSIX-level tracing of agent-emitted code via DFTracer LD_PRELOAD inside isolated subprocesses; and per-step decomposition of I/O into the final solution path versus exploration overhead (failed attempts, inspection, verification, retries). We evaluate correctness-passing agent-generated workflows across several models and scientific tasks, then compare them with expert implementations. The results show that valid agent-generated scientific code can issue far more POSIX operations and read substantially more data than expert baselines, and that exploration overhead varies by model. The takeaway is that correctness alone is not a sufficient proxy for I/O efficiency, and storage behavior should be measured directly before deploying agent-generated workflows on shared HPC or cloud storage.","hasAbstract":true,"lede":"LLM coding agents are increasingly used to generate scientific workflows, but evaluations stop at output correctness.","links":{"poster":"https://grc.iit.edu/papers/2026/yildirim-2026-correct-is-not-io-efficient-9d2f-poster.pdf","bibtex":"https://grc.iit.edu/papers/2026/yildirim-2026-correct-is-not-io-efficient-9d2f-bibtex.bib","citation":"https://grc.iit.edu/papers/2026/yildirim-2026-correct-is-not-io-efficient-9d2f-citation.txt"},"tags":["HPC","I/O Analysis","LLM Agents","Scientific Workflows","Storage Performance"],"_projectIds":["iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"bateman2026agentrecall","slug":"bateman-2026-agentrecall-339d","title":"AgentRecall: Provenance and Rewind for Multi-Agent Workflows","authors":["K. Bateman","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Bateman_Keith_AgentRecall%20-%20keith%20bateman.pdf"},"_projectIds":["dtio","iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"gonzalez2026chronologposter","slug":"gonzalez-2026-chronolog-tiered-log-ff8c","title":"ChronoLog: Distributed Shared Tiered Log Store","authors":["E. Gonzalez","K. Feng","I. Brodkin","K. Chard","A. Kougkas","X.-H. Sun"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/ChronoLog_Poster_v6_crop%20-%20Kun%20Feng.pdf"},"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"rajesh2026applicationsio","slug":"rajesh-2026-applications-do-io-8560","title":"Applications do I/O. What if files actually went... somewhere else?","authors":["N. Rajesh","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"program":"https://gcasr.org/2026/posters"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"pawar2026semanticsearch","slug":"pawar-2026-semantic-search-agent-discovery-577f","title":"Benchmarking the Performance of Semantic Search Techniques for Agent Discovery","authors":["R. Pawar","L. Logan","X.-H. Sun","A. Kougkas"],"venue":"13th Greater Chicago Area Systems Research Workshop (GCASR 2026)","type":"Poster","entryType":"misc","date":"May, 2026","year":2026,"era":"iit","month":5,"hasAbstract":false,"links":{"poster":"https://gcasr.org/2026/pdfs/posters/Semantic_Search_Poster%20-%20Rajni%20Pawar.pdf"},"_projectIds":["hermes","iowarp"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"chittyvenkata2026pagedeviction","slug":"chitty-venkata-2026-pagedeviction-3f8a","title":"PagedEviction: Structured Block-wise KV Cache Pruning for Efficient Large Language Model Inference","authors":["K. Chitty-Venkata","J. Ye","S. Raskar","A. Kougkas","X.-H. Sun","M. Emani","V. Vishwanath","B. Nicolae"],"venue":"Findings of the Association for Computational Linguistics (EACL 2026)","type":"Conference","entryType":"inproceedings","date":"March, 2026","year":2026,"era":"iit","month":3,"doi":"10.18653/v1/2026.findings-eacl.168","abstract":"KV caching significantly improves the efficiency of Large Language Model (LLM) inference by storing attention states from previously processed tokens, enabling faster generation of subsequent tokens. However, as sequence length increases, the KV cache quickly becomes a major memory bottleneck. To address this, we propose PagedEviction, a novel fine-grained, structured KV cache pruning strategy that enhances the memory efficiency of vLLM\'s PagedAttention. Unlike existing approaches that rely on attention-based token importance or evict tokens across different vLLM pages, PagedEviction introduces an efficient block-wise eviction algorithm tailored for paged memory layouts. Our method integrates seamlessly with PagedAttention without requiring any modifications to its CUDA attention kernels. We evaluate PagedEviction across Llama-3.1-8B-Instruct, Llama-3.2-1B-Instruct, and Llama-3.2-3B-Instruct models on the LongBench benchmark suite, demonstrating improved memory usage with better accuracy than baselines on long context tasks.","hasAbstract":true,"lede":"To address this, we propose PagedEviction, a novel fine-grained, structured KV cache pruning strategy that enhances the memory efficiency of vLLM\'s PagedAttention.","pages":"3207\u20133218","links":{"pdf":"https://aclanthology.org/2026.findings-eacl.168.pdf"},"tags":["KV Cache","Compression","LLM Inference Serving"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tallent2026dataflowdrs","slug":"tallent-2026-dataflowdrs-5e21","title":"DataFlowDrs: Automating Performance Optimization of Data Flow Within HPC Workflows","authors":["N. R. Tallent","M. Tang","J. Firoz","Z. Peng","L. Guo","A. Kougkas","X.-H. Sun"],"venue":"IEEE Transactions on Parallel and Distributed Systems","type":"Journal","entryType":"article","date":"2026","year":2026,"era":"iit","doi":"10.1109/TPDS.2026.3722592","hasAbstract":false,"pages":"1\u201318","_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2025s3roofline","slug":"tang-2025-s3-roofline-c7bd","title":"Quantifying AWS S3 I/O Performance Boundaries Using the Roofline Model","authors":["M. Tang","Z. Zhu","L. Guo","J. G. Bandy","T. Carlson","S. Neuwirth","A. Kougkas","X.-H. Sun","N. R. Tallent"],"venue":"10th International Parallel Data Systems Workshop (PDSW 2025), Proceedings of the SC \'25 Workshops","type":"Workshop","entryType":"inproceedings","date":"November, 2025","year":2025,"era":"iit","month":11,"doi":"10.1145/3731599.3767513","abstract":"High-performance computing facilities increasingly form hybrid environments that integrate cloud services. To avoid cumbersome network transfers when sharing data, a new class of storage gateways map a subset of facility storage to a cloud counterpart and automatically manage data mirroring. However, the performance characteristics of accessing AWS\'s S3 from HPC systems using different methods and patterns remains poorly understood. This paper presents a roofline-based analysis of three S3 integration approaches: NFS-mounted AWS Storage Gateway, data migration through Storage Gateway, and direct S3 API transfers. We extend I/O roofline modeling to characterize operational intensity and bandwidth ceilings across varying data sizes and access patterns. Our experimental evaluation demonstrates significant performance differences between access methods, with POSIX I/O on NFS Storage Gateway achieving up to 6.4\xd7 higher bandwidth than other approaches for large transfers. The roofline analysis reveals distinct characteristics for each method, enabling informed selection of S3 integration strategies.","hasAbstract":true,"pages":"1415\u20131423","links":{"pdf":"https://grc.iit.edu/papers/2025/tang-2025-s3-roofline-c7bd.pdf"},"tags":["I/O","Cloud Storage","AWS S3","Roofline Model","Performance Analysis"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"islam2025towardsaidriven","slug":"islam-2025-towards-ai-driven-01ae","title":"Towards an AI-driven scientific workflow","authors":["S. Islam","J. Cernuda","I. Muradli","A. Kougkas","X.-H. Sun"],"venue":"21st IEEE International Conference on eScience (eScience \'25), September 15-18, 2025","type":"Technical Report","entryType":"misc","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/escience65000.2025.00074","hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/islam-2025-towards-ai-driven-01ae-poster.pdf"},"tags":["AI","LLM","MCP","HPC"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lumsden2025optimizing","slug":"lumsden-2025-optimizing-rex5","title":"Optimizing I/O for an Exascale Implicit Kinetic Plasma Simulation using the Rabbit Storage System","authors":["I. Lumsden","H. Devarajan","I. Yildirim","S. Markidis","A. Hu","I. Peng","L. Pennati","D. Yokelson","S. Brink","O. Pearce","T. Scogland","B. R. de Supinski","G. L. Delzanno","A. Kougkas","X.-H. Sun","M. Taufer"],"venue":"REX-IO 2025 in conjunction with IEEE Cluster 2025 in Edinburgh, Scotland","type":"Workshop","entryType":"inproceedings","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/CLUSTERWorkshops65972.2025.11164212","hasAbstract":false,"pages":"1\u20136","links":{"pdf":"https://grc.iit.edu/papers/2025/lumsden-2025-optimizing-rex5.pdf"},"tags":["HPC","Rabbit Nodes","I/O Accelerators","I/O Optimization","iPIC3D","IOR"],"_projectIds":[],"_funding":[{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"muradli2025insightsgpudirect","slug":"muradli-2025-insights-gpudirect-02b4","title":"Insights into GPUDirect Data Transfer through NIXL Benchmarking","authors":["I. Muradli","J. Ye","L. Logan","A. Kougkas","X.-H. Sun"],"venue":"21st IEEE International Conference on eScience (eScience \'25), September 15-18, 2025","type":"Technical Report","entryType":"misc","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/escience65000.2025.00075","hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/muradli-2025-insights-gpudirect-02b4-poster.pdf"},"tags":["GPU","GPUDirect Storage","NIXL","Benchmarking"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025dtio","slug":"bateman-2025-dtio-e77d","title":"DTIO: Data Stack for AI-driven Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"The 37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3733723.3733736","abstract":"HPC, Big Data Analytics, and Machine Learning have become in- creasingly intertwined as popular models such as LLMs and Diffusion Models have been driving discovery in scientific fields. However, each of these domains has its own storage infrastructure with unique I/O interfaces and storage systems, requiring feature sets that are often incompatible. Users with experience in one domain lack the expertise to change their applications to match the data stacks of the other domains, necessitating expensive conversions. There is a need for a transparent solution for the unification of disparate data stacks for the triple convergence of HPC, Big Data, and ML that can provide the required functionality while achieving higher performance. To better support converged HPC, Big Data, and ML workflows, this paper proposes DTIO, a scalable I/O runtime that unifies the disparate I/O stack for modern scientific ML workflows. DTIO utilizes a unique DataTask abstraction to express the move- ment of data, its ordering, and its dependencies on other data as a task. DTIO achieves a unification of scientific and ML workflows by utilizing intelligent mapping of interfaces, and automatically de- termines the best method to relate their unique semantics. DTIO\'s online translation with DataTask caching can improve performance by 49.6% compared to offline translation methods. DTIO also offers numerous optimizations, such as asynchronous I/O and aggregation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2025/bateman-2025-dtio-e77d.pdf"},"tags":["Task Systems","Data Stacks","Systems for AI Workflows"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"CNS-2346504","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2025ioworkflows","slug":"tang-2025-ioworkflows-a9f3","title":"Analyzing I/O Patterns and Dataflow in HPC Workflows","authors":["M. Tang","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The 37h International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Technical Report","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/tang-2025-ioworkflows-a9f3-poster.pdf"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"xu2025richoperators","slug":"xu-2025-rich-operators-a3f2","title":"Rich Operators for Advanced In Situ Processing","authors":["H. Xu","A. Kougkas","X.-H. Sun"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/3780_Hua.pdf"},"tags":["HPC","Metadata Management","Storage"],"_projectIds":["coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"ye2025characterizingbehavior","slug":"ye-2025-characterizing-behavior-f631","title":"Characterizing the Behavior and Impact of KV Caching on Transformer Inferences under Concurrency","authors":["J. Ye","J. Cernuda","A. Maurya","X.-H. Sun","A. Kougkas","B. Nicolae"],"venue":"The 39th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1109/IPDPS64566.2025.00108","abstract":"Pre-training of LLMs and transformers is known to take weeks if not months even with powerful HPC systems. However, inferences are an equally important problem: once pre-trained, the model needs to serve a large number of inferences submitted under concurrency by multiple users. Thus, speeding up each inference request is instrumental in achieving high throughput and latency at scale. To avoid redundant recomputation in each decode iteration, a Key-Value (KV) cache is used to store previously computed keys (K) and values (V), speeding up token generation. GPU memory is primarily consumed by model weights and the remainder is used by the KV cache. Thus, the free GPU space available to the KV cache is a scarce resource that needs to be managed in an efficient way in order to minimize the overhead of redundant recomputations. There are many optimizations applied in this context: batching of inference requests to enable them to run in the same forward pass (and thus increase the parallelism and inference throughput), different KV cache eviction policies (simply drop KV entries and recompute them later vs. swap to host memory), etc. Under these circumstances, the decision of what batching strategy, what KV cache eviction policy to apply and how the KV cache impacts the inference performance is non-trivial. Unlike the case of pre-training, state-of-art studies are scarce in this context. To fill this gap, in this paper we study the impact of KV caching. Specifically, we instrument vLLM to measure and analyze fine-grain metrics (token throughput, KV cache memory access patterns, load balancing of the forward passes), during different inference stages (prefill, decode) in several scenarios that involve concurrent inference requests using several benchmarks. Based on the measurements and associated observations, we identify several opportunities to improve the design of inference frameworks. Index Terms-LLM inference, KV cache profiling, access pattern characterization.","hasAbstract":true,"lede":"To fill this gap, in this paper we study the impact of KV caching.","links":{"pdf":"https://grc.iit.edu/papers/2025/ye-2025-characterizing-behavior-f631.pdf"},"tags":["LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"CSSI-2411386","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2025wisio","slug":"yildirim-2025-wisio-45f7","title":"WisIO: Automated I/O Bottleneck Detection with Multi-Perspective Views for HPC Workflows","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The 39th ACM International Conference on Supercomputing (ICS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3721145.3725742","abstract":"Modern HPC workloads involve large data transfers that can become bottlenecks. Existing analysis tools identify bottle- necks from per-file performance data but have limitations in parallelizability and rigid heuristic-based rules, necessitating an automated, efficient, and multi-perspective solution. We designed an automated tool, WisIO, that enables parallel and distributed analysis of multi-terabyte-scale workflow performance data. WisIO examines performance data from multiple perspectives, uses metric-driven bottleneck classifi- cation, and allows extensible mapping of bottlenecks to root causes. Experimental results demonstrate that WisIO\'s multi- perspective views substantially improve bottleneck coverage, showing an average increase of up to 805\xd7 when compared to analyzing performance data from a single perspective. In our performance evaluation, WisIO\'s metric-driven classification processed 340K bottlenecks per second, while its reasoning engine handled around 35K bottlenecks per sec- ond. In an analysis of five real-world HPC workloads, WisIO demonstrated up to 11\xd7 faster analysis time and identified up to 144x more bottlenecks compared to existing solutions.","hasAbstract":true,"lede":"Modern HPC workloads involve large data transfers that can become bottlenecks.","links":{"pdf":"https://grc.iit.edu/papers/2025/yildirim-2025-wisio-45f7.pdf"},"tags":["HPC","Workflows","I/O Analysis","I/O Bottleneck Detection","WisIO","LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2025unifiedstack","slug":"bateman-2025-unified-data-stack-8de5","title":"A Unified Data Stack for AI Workflows","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","B. Nicolae","F. Cappello","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"sonar2025chronologai","slug":"sonar-2025-chronolog-ai-78fe","title":"ChronoLog & AI: A Scalable, Collaborative Solution for LLM Conversation Logging & Retrieval","authors":["S. Sonar","J. Cernuda","A. Kougkas","X.-H. Sun"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/0249-Sonar.pdf"},"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"rajesh2025eris","slug":"rajesh-2025-eris-a1a8","title":"Eris: A Trace-Driven Gym for AI-Powered Cache Optimization in HPC","authors":["N. Rajesh","K. Bateman","X.-H. Sun","A. Kougkas"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"program":"https://ssdbm.org/2025/accepted-posters.html"},"_projectIds":["coeus"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"ye2025asyncoffload","slug":"ye-2025-accelerate-llm-inference-1ae6","title":"Accelerate LLM inference with Asynchronous model offload","authors":["J. Ye","A. Kougkas","X.-H. Sun","B. Nicolae"],"venue":"37th International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Poster","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://ssdbm.org/2025/assets/poster/8884-Jie.pdf"},"_projectIds":["storehub"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"presented","visibility":"public"},{"citeKey":"cernuda2024jarvis","slug":"cernuda-2024-jarvis-3b52","title":"Jarvis: Towards a Shared, User-Friendly, and Reproducible, I/O Infrastructure.","authors":["J. Cernuda","L. Logan","N. Lewis","S. Byna","X.-H. Sun","A. Kougkas"],"venue":"The International Parallel Data Systems Workshop (PDSW\'24)","type":"Workshop","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"abstract":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters. However, computing environments for developing tools to harness these technologies are not easily available to researchers. This work showcases the need for a new high-pace, heterogeneous I/O research cluster and presents a novel software deployment framework named Jarvis to manage its hardware diversity. Jarvis is an extensible Python framework that allows users to create Packages that deploy, manage, and monitor software, including complex applications (e.g., scientific simulations), support tools (e.g., Darshan, GDB), and storage systems (e.g., Lustre, DAOS). These packages can be combined to form complex deployment Pipelines. To ensure pipelines are portable across hardware, Jarvis defines a novel Resource Graph schema file, which is a snapshot of a cluster\'s machine-specific information. This schema can be queried by Jarvis packages to deploy software across diverse hardware compositions with minimal user effort. Index Terms-deployment, HPC, hardware abstraction, resource management, I/O, Python","hasAbstract":true,"lede":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-jarvis-3b52.pdf"},"tags":["Deployment","HPC","Hardware Abstraction","I/O","Python","Resource Management"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2024dftracer","slug":"devarajan-2024-dftracer-8fcb","title":"DFTracer: An Analysis-Friendly Data Flow Tracer for AI-Driven Workflows","authors":["H. Devarajan","L. Pottier","K. Velusamy","H. Zheng","I. Yildirim","O. Kogiou","W. Yu","A. Kougkas","X.-H. Sun","J.-S. Yeom","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00023","abstract":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight. These workflows require a cohesive set of performance analysis tools to provide a comprehensive understanding of data exchange patterns in HPC systems. However, current tools are not designed to work with an AI-based I/O software stack that requires tracing at multiple levels of the application. To this end, we developed a data flow tracer called DFTracer to capture data-centric events from workflows and the I/O stack to build a detailed understanding of the data exchange within AI-driven workflows. DFTracer has the following three novel features, including a unified interface to capture trace data from different layers in the software stack, a trace format that is analysis-friendly and optimized to support efficiently loading multi-million events in a few seconds, and the capability to tag events with workflow-specific context to perform domain-centric data flow analysis for workflows. Additionally, we demonstrate that DFTracer has a 1.44x smaller runtime overhead and 1.3-7.1x smaller trace size than state-of-the-art tracing tools such as Score-P, Recorder, and Darshan. Moreover, with AI-driven workflows, Score-P, Recorder, and Darshan cannot find I/O accesses from dynamically spawned processes, and their load performance of 100M events is three orders of magnitude slower than DFTracer. In conclusion, we demonstrate that DFTracer can capture multi-level performance data, including contextual event tagging with a low overhead of 1-5% from AI-driven workflows such as MuMMI and Microsoft\'s Megatron Deepspeed running on large-scale HPC systems. Index Terms-deep learning, workflows, I/O, tracer, multi- level, application apis, system calls, transparent, interception.","hasAbstract":true,"lede":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight.","links":{"pdf":"https://grc.iit.edu/papers/2024/devarajan-2024-dftracer-8fcb.pdf"},"tags":["Deep Learning","Workflows","I/O Tracing"],"_projectIds":["wisio"],"_funding":[{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true},{"agency":"NIH","award":"75N91019D00024","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"gainaru2024deriveor","slug":"gainaru-2024-derive-or-4aad","title":"To Derive or Not to Derive: I/O Libraries Take Charge of Derived Quantities Computation","authors":["A. Gainaru","G. Eisenhauer","N. Podhorszki","L. Dulac","Q. Gong","A. Kougkas","J. Lofstead","X.-H. Sun","S. Klasky"],"venue":"IEEE/SBC 36th International Symposium on Computer Architecture and High Performance Computing (SBAC-PAD 2024), Hawaii, USA","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sbac-pad63648.2024.00030","abstract":"The ever-increasing volume of data produced by HPC simulations necessitates scalable methods for data explo- ration and knowledge extraction. Scientific data analysis often in- volves complex queries across distributed datasets, requiring ma- nipulation of multiple primary variables and generating derived data that needs to be handled efficiently, creating challenges for applications that need to parse many large datasets. Relying on individual applications to handle all intermediate data generally leads to redundant computations across studies and unnecessary data transfers. In this paper, we investigate the performance of different approaches where applications define derived variables as quantities of interest (QoIs) and offload the computation and transfer of these QoIs to the I/O library. This significantly reduces redundancy and optimizes data movement across the distributed storage and processing infrastructure by allowing control over when and where derived variables are computed. We present a detailed analysis of the performance-storage trade-offs associated with different solutions and showcase results for our study on two large-scale datasets created from climate and combustion simulations.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/gainaru-2024-derive-or-4aad.pdf"},"tags":["HPC Analysis","Large-Scale I/O","Derived Variables","Quantities of Interest"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2024megammap","slug":"logan-2024-megammap-cbda","title":"MegaMmap: Blurring the Boundary Between Memory and Storage for Data-Intensive Workloads","authors":["L. Logan","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00114","abstract":"Large-scale data analytics, scientific simulation, and deep learning codes in HPC perform massive computations on data greatly exceeding the bounds of main memory. These out-of-core al- gorithms suffer from severe data movement penalties, programming complexity, and limited code reuse. To solve this, HPC sites have steadily increased DRAM capacity. However, this is not sustainable due to financial and environmental costs. A more elegant, low-cost, and portable solution is to expand memory to distributed multi- tiered storage. In this work, we propose MegaMmap: a software distributed shared memory (DSM) that enlarges effective memory capacity through intelligent tiered DRAM and storage management. MegaMmap provides workload-aware data organization, eviction, and prefetching policies to reduce DRAM consumption while ensur- ing speedy access to critical data. A variety of memory coherence optimizations are provided through an intuitive hinting system. Evaluations show that various workloads can be executed with a fraction of the DRAM while offering competitive performance.","hasAbstract":true,"lede":"We propose MegaMmap: a software distributed shared memory (DSM) that enlarges effective memory capacity through intelligent tiered DRAM and storage management.","links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-megammap-cbda.pdf","code":"https://github.com/grc-iit/mega_mmap"},"tags":["Memory","Storage","Hierarchical Storage","HPC","Operating Systems","LABIOS"],"_projectIds":["labios"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"ye2024uncoveroverhead","slug":"ye-2024-uncover-overhead-3814","title":"Uncover the Overhead and Resource Usage for Handling KV Cache Overflow in LLM Inference","authors":["J. Ye","B. Nicolae","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Technical Report","entryType":"misc","date":"November, 2024","year":2024,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2024/ye-2024-uncover-overhead-3814-poster.pdf"},"tags":["KV Cache","LLM Inference"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2024dayu","slug":"tang-2024-dayu-f286","title":"DaYu: Optimizing Distributed Scientific Workflows by Decoding Dataflow Semantics and Dynamics","authors":["M. Tang","J. Cernuda","J. Ye","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"2024 IEEE International Conference on Cluster Computing (CLUSTER\'24)","type":"Conference","entryType":"inproceedings","date":"September, 2024","year":2024,"era":"iit","month":9,"doi":"10.1109/cluster59578.2024.00038","abstract":"The combination of ever-growing scientific datasets and distributed workflow complexity creates I/O performance bottlenecks due to data volume, velocity, and variety. Although the increasing use of descriptive data formats (e.g., HDF5, netCDF) helps organize these datasets, it also introduces obscure bottlenecks due to the need to translate high-level operations into file addresses and then into low-level I/O operations. To address this challenge, we introduce DaYu, a method and toolset for analyzing (a) semantic relationships between logical datasets and file addresses, (b) how dataset operations translate into I/O, and (c) the combination across entire workflows. DaYu\'s analysis and visualization enable the identification of critical bottlenecks and the reasoning about remediation. We describe our methodology and propose optimization guidelines. Evaluation on scientific workflows demonstrates up to a 3.7x performance improvement in I/O time for obscure bottlenecks. The time and storage overhead for DaYu\'s time-ordered data are typically under 0.2% of runtime and 0.25% of data volume, respectively.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/tang-2024-dayu-f286.pdf"},"tags":["Data Analytics","Modeling","Performance Measurement","Tools","Workflow Optimization"],"_projectIds":["portus"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2024hstream","slug":"cernuda-2024-hstream-3043","title":"HStream: A hierarchical data streaming engine for high-throughput scientific applications","authors":["J. Cernuda","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673150","abstract":"Data streaming is gaining traction in high-performance computing (HPC) as a mechanism for continuous data transfer, but remains underutilized as a processing paradigm due to the inadequacy of existing technologies, which are primarily designed for cloud archi- tectures and ill-equipped to tackle HPC-specific challenges. This work introduces HStream, a novel data management design for out-of-core data streaming engines. Central to the HStream design is the separation of data and computing planes at the task level. By managing them independently, issues such as memory thrashing and back-pressure, caused by the high volume, velocity, and bursti- ness of I/O in HPC environments, can be effectively addressed at runtime. Specifically, HStream utilizes adaptive parallelism and hi- erarchical memory management, enabled by this design paradigm, to alleviate memory pressure and enhance system performance. These improvements enable HStream to match the performance of state-of-the-art HPC streaming engines and achieve up to a 1.5x reduction in latency under high data loads.","hasAbstract":true,"lede":"Data streaming is gaining traction in high-performance computing (HPC) as a mechanism for continuous data transfer.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hstream-3043.pdf"},"tags":["Data Streaming","HPC","Hierarchical Storage","Elastic System","In-Transit Computing","LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true},{"agency":"DOE","award":"DE-SC0024593","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"ye2024viper","slug":"ye-2024-viper-0a1b","title":"Viper: A High-Performance I/O Framework for Transparently Updating, Storing, and Transferring Deep Neural Network Models","authors":["J. Ye","J. Cernuda","N. Rajesh","K. Bateman","O. Yildiz","T. Peterka","A. Nigmetov","D. Morozov","A. Kougkas","X.-H. Sun","B. Nicolae"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673070","abstract":"Scientific workflows increasingly need to train a DNN model in real-time during an experiment (e.g. using ground truth from a sim- ulation), while using it at the same time for inferences. Instead of sharing the same model instance, the training (producer) and infer- ence server (consumer) often use different model replicas that are kept synchronized. In addition to efficient I/O techniques to keep the model replica of the producer and consumer synchronized, there is another important trade-off: frequent model updates enhance infer- ence quality but may slow down training; infrequent updates may lead to less precise inference results. To address these challenges, we introduce Viper: a new I/O framework designed to determine a near- optimal checkpoint schedule and accelerate the delivery of the latest model updates. Viper builds an inference performance predictor to identify the optimal checkpoint schedule to balance the trade-off be- tween training slowdown and inference quality improvement. It also creates a memory-first model transfer engine to accelerate model delivery through direct memory-to-memory communication. Our experiments show that Viper can reduce the model update latency by \u2248 9x using the GPU-to-GPU data transfer engine and \u2248 3x using the DRAM-to-DRAM host data transfer. The checkpoint schedule obtained from Viper\'s predictor also demonstrates improved cumu- lative inference accuracy compared to the baseline of epoch-based solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/ye-2024-viper-0a1b.pdf","slides":"https://grc.iit.edu/papers/2024/ye-2024-viper-0a1b-slides.pptx"},"tags":["AI Workflows","Adaptive AI Model Checkpointing","Coupled Training and Inferences","Inferences During Partial Training","LABIOS"],"_projectIds":["deepio"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2024evaluationdaos","slug":"logan-2024-evaluation-daos-6eb2","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"SIGOPS Operating Systems Review (OSR\'24)","type":"Journal","entryType":"article","date":"June, 2024","year":2024,"era":"iit","month":6,"doi":"10.1145/3689051.3689058","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-evaluation-daos-6eb2.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2024hades","slug":"cernuda-2024-hades-e18c","title":"Hades: A Context-Aware Active Storage Framework for Accelerating Large-Scale Data Analysis","authors":["J. Cernuda","L. Logan","A. Gainaru","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 24th IEEE/ACM international Symposium on Cluster, Cloud and Internet Computing (CCGRID 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ccgrid59990.2024.00070","abstract":"Modern simulation workflows generate and analyze massive amounts of data using I/O libraries like Adios2 and NetCDF. Although extensive work has optimized the I/O processes during the simulation phase, executing analytical queries-which often require iterative traversals of large files for insights-is cumbersome and usually constrained by low I/O performance. Instead of waiting for the analysis phase to process queries, quantities can be derived asynchronously during data production and cached, speeding up future queries. In this work, we introduce a context-aware I/O layer named \'Hades.\' It is designed to efficiently derive insights from selected quantities without compromising overall workflow performance. Hades actively and asynchronously computes and stores these quantities while the data is in transit. Hades leverages a hierarchical buffering system with data access-aware prefetching to ensure quick and timely access to relevant data. It offers a flexible query interface empowering users to easily define derived quantities and provide control over data placement decisions. Hades is implemented using an Adios2 plugin engine and the Hermes buffering platform, enabling transparent use by any Adios-powered application or workflow. Experimental results demonstrate performance improvements by up to 3-4x for tested real-world scientific producer-consumer workflows. Index Terms-Active Storage, Hierarchical Storage, Context Awareness, Metadata Management, Data Operator, In-transit Computing","hasAbstract":true,"lede":"We introduce a context-aware I/O layer named \'Hades.\'","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hades-e18c.pdf"},"tags":["Active Storage","Hierarchical Storage","Context Awareness","Metadata Management","Data Operator","In-Transit Computing","Coeus"],"_projectIds":["coeus"],"_funding":[{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2024tunio","slug":"rajesh-2024-tunio-05a8","title":"TunIO: An AI-powered Framework for Optimizing HPC I/O","authors":["N. Rajesh","K. Bateman","S. Byna","J. L. Bez","A. Kougkas","X.-H. Sun"],"venue":"The 38th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ipdps57955.2024.00050","abstract":"I/O operations are a known performance bottleneck of HPC applications. To achieve good performance, users often employ an iterative multistage tuning process to find an optimal I/O stack configuration. However, an I/O stack contains multiple layers, such as high-level I/O libraries, I/O middleware, and parallel file systems, and each layer has many parameters. These parameters and layers are entangled and influenced by each other. The tuning process is time-consuming and complex. In this work, we present TunIO, an AI- powered I/O tuning framework that implements several techniques to balance the tuning cost and performance gain, including tuning the high- impact parameters first. Furthermore, TunIO analyzes the application source code to extract its I/O kernel while retaining all statements necessary to perform I/O. It utilizes a smart selection of high-impact configuration parameters of the given tuning objective. Finally, it uses a novel Reinforcement Learning (RL)-driven early stopping mechanism to balance the cost and performance gain. Experimental results show that TunIO leads to a reduction of up to \u2248 73% in tuning time while achieving the same performance gain when compared to H5Tuner. It achieves a significant performance gain/cost of 208.4 MBps/min (I/O bandwidth for each minute spent in tuning) over existing approaches under our testing. Index Terms-AI-powered I/O tuning, storage stack tuning, autotun- ing, source code transformations, and I/O performance optimization","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/rajesh-2024-tunio-05a8.pdf"},"tags":["AI for I/O","I/O Stack Tuning"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lee2023datalifecycles","slug":"lee-2023-data-lifecycles-c393","title":"Data Flow Lifecycles for Optimizing Workflow Coordination","authors":["H. Lee","L. Guo","M. Tang","J. Firoz","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Conference","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3581784.3607104","abstract":"A critical performance challenge in distributed scientific workflows is coordinating tasks and data flows on distributed resources. To guide these decisions, this paper introduces data flow lifecycle anal- ysis. Workflows are commonly represented using directed acyclic graphs (DAGs). Data flow lifecycles (DFL) enrich task DAGs with data objects and properties that describe data flow and how tasks interact with that flow. Lifecycles enable analysis from several important perspectives: task, data, and data flow. We describe rep- resentation, measurement, analysis, visualization, and opportunity identification for DFLs. Our measurement is both distributed and scalable, using space that is constant per data file. We use lifecycles and opportunity analysis to reason about improved task placement and reduced data movement for five scientific workflows with dif- ferent characteristics. Case studies show improvements of 15x, 1.9\xd7, and 10-30x. Our work is implemented in the DataLife tool.","hasAbstract":true,"lede":"To guide these decisions, this paper introduces data flow lifecycle anal- ysis.","pages":"1\u201315","links":{"pdf":"https://grc.iit.edu/papers/2023/lee-2023-data-lifecycles-c393.pdf"},"tags":["Data Analytics","Performance Measurement","Modeling","Tools"],"_projectIds":[],"_funding":[{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2023semanticworkflow","slug":"tang-2023-semantic-workflow-e12d","title":"Optimizing Workflow Performance by Elucidating Semantic Data Flow","authors":["M. Tang","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'23)","type":"Technical Report","entryType":"misc","date":"November, 2023","year":2023,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2023/tang-2023-semantic-workflow-e12d-poster.pdf"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023exploringimpacts","slug":"yildirim-2023-exploring-impacts-090b","title":"Exploring the Impacts of Multiple I/O Metrics in Identifying I/O Bottlenecks","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Technical Report","entryType":"misc","date":"November, 2023","year":2023,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2023/yildirim-2023-exploring-impacts-090b-poster.pdf"},"tags":["I/O Analysis","I/O Metrics","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023iomax","slug":"yildirim-2023-iomax-3919","title":"IOMax: Maximizing Out-of-Core I/O Analysis Performance on HPC Systems","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Parallel Data Systems Workshop (PDSW\'23)","type":"Workshop","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3624062.3624191","abstract":"I/O analysis is an essential task for improving the performance of scientific applications on high-performance computing (HPC) systems. However, current analysis tools, which often use data drilling techniques (iterative exploration for deeper insights), treat every query independently and do not optimize column data for data-slicing (extracting specific data subsets), resulting in subpar querying performance. In this paper, we designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces. IOMax utilizes a novel query optimization technique to improve the query performance by 8.6x while reducing the memory footprint required for analysis by 11x. Additionally, it employs data transformation techniques to improve data-slicing performance by up to 11.4x. In conclusion, IOMax optimizes I/O analysis for scientific workflows on the Lassen supercomputer, resulting in up to 7x improvement.","hasAbstract":true,"lede":"We designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces.","links":{"pdf":"https://grc.iit.edu/papers/2023/yildirim-2023-iomax-3919.pdf"},"tags":["I/O Analysis","Out-of-Core Analysis","Data Drilling","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2023evaluationdaos","slug":"logan-2023-evaluation-daos-a960","title":"An Evaluation of DAOS for Simulation and Deep Learning HPC Workloads","authors":["L. Logan","J. Lofstead","A. Kougkas","X.-H. Sun"],"venue":"The 3rd Workshop on Challenges and Opportunities of Efficient and Performant Storage Systems (CHEOPS\'23)","type":"Workshop","entryType":"inproceedings","date":"May, 2023","year":2023,"era":"iit","month":5,"doi":"10.1145/3578353.3589542","abstract":"Traditionally, distributed storage systems have relied upon the interfaces provided by OS kernels to interact with stor- age hardware. However, much research has shown that OSes impose serious overheads on every I/O operation, especially on high-performance storage and networking hardware (e.g., PMEM and 200GBe). Thus, distributed storage stacks are being re-designed to take advantage of this modern hard- ware by utilizing new hardware interfaces which bypass the kernel entirely. However, the impact of these optimizations have not been well-studied for real HPC workloads on real hardware. In this work, we provide a comprehensive evalua- tion of DAOS: a state-of-the-art distributed storage system which re-architects the storage stack from scratch for mod- ern hardware. We compare DAOS against traditional storage stacks and demonstrate that by utilizing optimal interfaces to hardware, performance improvements of up to 6x can be observed in real scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2023/logan-2023-evaluation-daos-a960.pdf"},"tags":["Distributed Computing","Distributed Storage","Flash Memory","Machine Learning","Parallel Computing","Phase Change Memory"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"bateman2022luxio","slug":"bateman-2022-luxio-2487","title":"LuxIO: Intelligent Resource Provisioning and Auto-Configuration for Storage Services","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","J. Ye","S. Herbein","A. Kougkas","X.-H. Sun"],"venue":"The 29th edition of the IEEE International Conference on High Performance Computing, Data, and Analytics (HiPC\'22)","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/hipc56025.2022.00041","abstract":"Abstract-Storage in HPC is typically a single Remote and Static Storage (RSS) resource. However, applications demonstrate diverse I/O requirements that can be better served by a multi-storage approach. Cur- rent practice employs ephemeral storage systems running on either node- local or shared storage resources. Yet, the burden of provisioning and configuring intermediate storage falls solely on the users, while global job schedulers offer little to no support for custom deployments. This lack of support often leads to over- or under-provisioning of resources and poorly configured storage systems. To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service. LuxIO constructs storage deployments configured to best match I/O require- ments. LuxIO-tuned storage services show performance improvements up to 2x across common applications and benchmarks, while introducing minimal overhead of 93.40 ms on top of existing job scheduling pipelines. LuxIO improves resource utilization by up to 25% in select workflows.","hasAbstract":true,"lede":"To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service.","links":{"pdf":"https://grc.iit.edu/papers/2022/bateman-2022-luxio-2487.pdf"},"tags":["Resource Provisioning","I/O Behavior","Storage Auto-Tuning","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2022labstor","slug":"logan-2022-labstor-f69d","title":"LabStor: A Modular and Extensible Platform for Developing High-Performance, Customized I/O Stacks in Userspace","authors":["L. Logan","J. Cernuda","J. Lofstead","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Conference","entryType":"inproceedings","date":"November, 2022","year":2022,"era":"iit","month":11,"doi":"10.1109/sc41404.2022.00028","abstract":"Traditionally, I/O systems have been developed within the confines of a centralized OS kernel. This led to monolithic and rigid storage systems that are limited by low development speed, expressiveness, and performance. Various assumptions are imposed including reliance on the UNIX-file abstraction, the POSIX standard, and a narrow set of I/O policies. However, this monolithic design philosophy makes it difficult to develop and deploy new I/O approaches to satisfy the rapidly-evolving I/O requirements of modern scientific applications. To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks. Single-purpose I/O modules (e.g, I/O schedulers) can be developed in the comfort of userspace and released as plug-ins, while end-users can compose these modules to form workload- and hardware-specific I/O stacks. Evaluations show that by switching to a fully modular design, tailored I/O stacks can yield performance improvements of up to 60% in various applications.","hasAbstract":true,"lede":"To this end, we propose LabStor: a modular and extensible platform for developing high-performance, customized I/O stacks.","links":{"pdf":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d.pdf","slides":"https://grc.iit.edu/papers/2022/logan-2022-labstor-f69d-slides.pdf"},"tags":["Clouds and Distributed Computing","Programming Frameworks","System Software","ChronoLog"],"_projectIds":["chronolog"],"_funding":[{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2022multifacetedapproach","slug":"yildirim-2022-multifaceted-approach-da2d","title":"A Multifaceted Approach to Automated I/O Bottleneck Detection for HPC Workloads","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Poster","entryType":"misc","date":"November, 2022","year":2022,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d.pdf","poster":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d-poster.pdf"},"tags":["I/O Characterization","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2022stimulus","slug":"devarajan-2022-stimulus-4b4c","title":"Stimulus: Accelerate Data Management for Scientific AI applications in HPC","authors":["H. Devarajan","A. Kougkas","H. Zheng","V. Vishwanath","X.-H. Sun"],"venue":"The 22nd IEEE/ACM International Symposium on Cluster, Cloud and Internet Computing (CCGRID\'22), May 16-19, 2022","type":"Conference","entryType":"inproceedings","date":"May, 2022","year":2022,"era":"iit","month":5,"doi":"10.1109/ccgrid54584.2022.00020","abstract":"Modern scientific workflows couple simulations with AI-powered analytics by frequently exchanging data to accelerate time-to-science to reduce the complexity of the simulation planes. However, this data exchange is limited in performance and portability due to a lack of support for scientific data formats in AI frameworks. We need a cohesive mechanism to effectively integrate at scale complex scientific data formats such as HDF5, PnetCDF, ADIOS2, GNCF, and Silo into popular AI frameworks such as TensorFlow, PyTorch, and Caffe. To this end, we designed Stimulus, a data management library for ingesting scientific data effectively into the popular AI frameworks. We utilize the StimOps functions along with StimPack abstraction to enable the integration of scientific data formats with any AI framework. The evaluations show that Stimulus outperforms several large-scale applications with different use-cases such as Cosmic Tagger (con- suming HDF5 dataset in PyTorch), Distributed FFN (consuming HDF5 dataset in TensorFlow), and CosmoFlow (converting HDF5 into TFRecord and then consuming that in TensorFlow) by 5.3x, 2.9x, and 1.9\xd7 respectively with ideal I/O scalability up to 768 GPUs on the Summit supercomputer. Through Stimulus, we can portably extend existing popular AI frameworks to cohesively support any complex scientific data format and efficiently scale the applications on large-scale supercomputers.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2022/devarajan-2022-stimulus-4b4c.pdf"},"tags":["HDF5","TensorFlow","Decoupled I/O","I/O Acceleration","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2021utilizingpersistent","slug":"logan-2021-utilizing-persistent-24d5","title":"Utilizing Persistent Memory in Parallel I/O Libraries","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-utilizing-persistent-24d5.pdf","poster":"https://grc.iit.edu/papers/2021/logan-2021-utilizing-persistent-24d5-poster.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021featurereduction","slug":"rajesh-2021-feature-reduction-4823","title":"Feature Reduction of Darshan Counters Using Evolutionary Algorithms","authors":["N. Rajesh","Q. Koziol","S. Byna","H. Tang","J. L. Bez","A. Kougkas","X.-H. Sun"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-feature-reduction-4823.pdf","poster":"https://grc.iit.edu/papers/2021/rajesh-2021-feature-reduction-4823-poster.pdf"},"tags":["Feature Reduction","Evolutionary Algorithms","Darshan"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"ye2021hdf5vol","slug":"ye-2021-hdf5-vol-4754","title":"HDF5 VOL Connector to Apache Arrow","authors":["J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/ye-2021-hdf5-vol-4754.pdf","poster":"https://grc.iit.edu/papers/2021/ye-2021-hdf5-vol-4754-poster.pdf"},"tags":["HDF5","Apache Arrow","Column store"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2021performanceanalysis","slug":"yildirim-2021-performance-analysis-f217","title":"Performance Analysis of Containerized OrangeFS in HPC Environment","authors":["I. Yildirim","M. Tang","A. Kougkas","X.-H. Sun"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/yildirim-2021-performance-analysis-f217.pdf","poster":"https://grc.iit.edu/papers/2021/yildirim-2021-performance-analysis-f217-poster.pdf"},"tags":["HPC","Singularity","Containers","Benchmarking"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2021hflow","slug":"cernuda-2021-hflow-2f5b","title":"HFlow: A Dynamic and Elastic Multi-Layered Data Forwarder","authors":["J. Cernuda","H. Devarajan","L. Logan","K. Bateman","N. Rajesh","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Conference","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00064","abstract":"Modern applications are highly data-intensive, leading to the well-known I/O bottleneck problem. Scientists have proposed the placement of fast intermediate storage resources which aim to mask the I/O penalties. To manage these resources, three core software abstractions are being used in leadership-class computing facilities: IO Forwarders, Burst Buffers, and Data Stagers. Yet, with the rise of multi-tenant deployment in HPC systems, these software abstractions are: managed and maintained in isolation, leading to inefficient interactions; allocated statically, leading to load imbalance; exclusively bifurcated between the intermediate storage, leading to under-utilization of resources, and, in many cases, do not support in-situ operations. To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm. HFlow introduces a unified data movement abstraction (the ByteFlow) providing data-independent tasks that can be executed anywhere and thus, enabling dynamic resource provisioning. Moreover, the processing elements executing the ByteFlows are designed to be ephemeral and, hence, enable elastic management of intermediate storage resources. Our results show that applications running under HFlow display an increase in performance of 3x when compared with state-of-the-art software solutions. Index Terms-Data streaming, I/O forwarding, elasticity, dynamicity, multi-tenant, data-intensive, I/O,data pipeline, in-transit","hasAbstract":true,"lede":"To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm.","links":{"pdf":"https://grc.iit.edu/papers/2021/cernuda-2021-hflow-2f5b.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2021pmemcpy","slug":"logan-2021-pmemcpy-f81c","title":"pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory","authors":["L. Logan","J. Lofstead","S. Levy","P. Widener","X.-H. Sun","A. Kougkas"],"venue":"The 1st Workshop on Re-envisioning Extreme-Scale I/O for Emerging Hybrid HPC Workloads (REX-IO\'21), in conjunction with the 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Workshop","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00098","abstract":"Persistent memory (PMEM) devices can achieve comparable performance to DRAM while providing significantly more capacity. This has made the technology compelling as an expansion to main memory. Rethinking PMEM as storage devices can offer a high performance buffering layer for HPC applications to temporarily, but safely store data. However, modern parallel I/O libraries, such as HDF5 and pNetCDF, are complicated and introduce significant software and metadata overheads when persisting data to these storage devices, wasting much of their potential. In this work, we explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory. We demonstrate that our approach is up to 2x faster than other popular parallel I/O libraries under real workloads.","hasAbstract":true,"lede":"We explore the potential of PMEM as storage through pMEMCPY: a simple, lightweight, and portable I/O library for storing data in persistent memory.","links":{"pdf":"https://grc.iit.edu/papers/2021/logan-2021-pmemcpy-f81c.pdf"},"tags":["Persistent Memory","Libraries","Memory Management","Memory Mapped I/O"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021apollo","slug":"rajesh-2021-apollo-dbd8","title":"Apollo: An ML-assisted Real-Time Storage Resource Observer","authors":["N. Rajesh","H. Devarajan","J. Cernuda","K. Bateman","L. Logan","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 30th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'21), June 21-25, 2021","type":"Conference","entryType":"inproceedings","date":"June, 2021","year":2021,"era":"iit","month":6,"doi":"10.1145/3431379.3460640","abstract":"Applications and middleware services, such as data placement en- gines, I/O scheduling, and prefetching engines, require low-latency access to telemetry data in order to make optimal decisions. However, typical monitoring services store their telemetry data in a database in order to allow applications to query them, resulting in significant latency penalties. This work presents Apollo: a low-latency mon- itoring service that aims to provide applications and middleware libraries with direct access to relational telemetry data. Monitoring the system can create interference and overhead, slowing down raw performance of the resources for the job. However, having a current view of the system can aid middleware services in making more optimal decisions which can ultimately improve the overall perfor- mance. Apollo has been designed from the ground up to provide low latency, using Publish\u2013Subscribe (Pub-Sub) semantics, and low overhead, using adaptive intervals in order to change the length of time between polling the resource for telemetry data and machine learning in order to predict changes to the telemetry data between actual resource polling. This work also provides some high level abstractions called I/O curators, which can further aid middleware libraries and applications to make optimal decisions. Evaluations showcase that Apollo can achieve sub-millisecond latency for acquir- ing complex insights with a memory overhead of 57MB and CPU overhead being only 7% more than existing state-of-the-art systems.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-apollo-dbd8.pdf"},"tags":["HPC","Machine Learning","Resource Monitoring","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2021dlio","slug":"devarajan-2021-dlio-0272","title":"DLIO: A Data-Centric Benchmark for Scientific Deep Learning Applications","authors":["H. Devarajan","H. Zheng","A. Kougkas","X.-H. Sun","V. Vishwanath"],"venue":"The 2021 IEEE/ACM International Symposium in Cluster, Cloud, and Internet Computing (CCGrid\'21), May 17 - 20, 2021 Best paper award","type":"Conference","entryType":"inproceedings","date":"May, 2021","year":2021,"era":"iit","month":5,"doi":"10.1109/ccgrid51090.2021.00018","abstract":"Deep learning has been shown as a successful method for various tasks, and its popularity results in numerous open-source deep learning software tools. Deep learning has been applied to a broad spectrum of scientific domains such as cosmology, particle physics, computer vision, fusion, and astrophysics. Scientists have performed a great deal of work to optimize the computational performance of deep learning frameworks. However, the same cannot be said for I/O perfor- mance. As deep learning algorithms rely on big-data volume and variety to effectively train neural networks accurately, I/O is a significant bottleneck on large-scale distributed deep learning training. This study aims to provide a detailed investigation of the I/O behavior of various scientific deep learning workloads running on the Theta supercomputer at Argonne Leadership Computing Facility. In this paper, we present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads. DLIO can be utilized to accurately emulate the I/O behavior of modern scientific deep learning applications. Using DLIO, application developers and system software solution architects can identify potential I/O bottlenecks in their applications and guide optimizations to boost the I/O performance leading to lower training times by up to 6.7x.","hasAbstract":true,"lede":"We present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads.","links":{"pdf":"https://grc.iit.edu/papers/2021/devarajan-2021-dlio-0272.pdf","video":"https://youtu.be/_rRhQBaHVs8"},"tags":["Deep Learning","Scientific Applications","Representative","Benchmark","Data-Intensive","I/O","Characterization","TensorFlow","Data Pipeline","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"grcAwards":"Best Paper Award (First Prize)","status":"published","visibility":"public"},{"citeKey":"devarajan2020hreplica","slug":"devarajan-2020-hreplica-44a8","title":"HReplica: A Dynamic Data Replication Engine with Adaptive Compression for Multi-Tiered Storage","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The 2020 IEEE International Conference on Big Data (Big Data\'20), December 10-13, 2020","type":"Conference","entryType":"inproceedings","date":"December, 2020","year":2020,"era":"iit","month":12,"doi":"10.1109/bigdata50022.2020.9378167","abstract":"As the diversity of big data applications increases, their requirements diverge and often conflict with one other. Managing this diversity in any supercomputer or data center is a major challenge for system designers. Data replication is a popular approach to meet several of these requirements, such as low latency, read availability, durability, etc. This approach can be enhanced using new modern heterogeneous hardware and soft- ware techniques such as data compression. However, both these enhancements work in isolation to the detriment of both. In this work, we present HReplica: a dynamic data replication engine which harmoniously leverages data compression and hierarchical storage to increase the effectiveness of data replication. We have developed a novel dynamic selection algorithm that facilitates the optimal matching of replication schemes, compression libraries, and tiered storage. Our evaluation shows that HReplica can improve scientific and cloud application performance by 5.2x when compared to other state-of-the-art replication schemes. Index Terms-data replication, dynamic, selection algorithm, multi-tiered, data compression, intelligent selection, dynamic programming, cloud application, scientific application, big data.","hasAbstract":true,"lede":"We present HReplica: a dynamic data replication engine which harmoniously leverages data compression and hierarchical storage to increase the effectiveness of data replication.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hreplica-44a8.pdf"},"tags":["Data Replication","Dynamic","Selection Algorithm","Multi-Tiered","Data Compression","Intelligent Selection","Dynamic Programming","Cloud Application","Scientific Applications","Big Data","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020dynamicmulti","slug":"devarajan-2020-dynamic-multi-ef19","title":"A Dynamic Multi-Tiered Storage System for Extreme Scale Computing","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-dynamic-multi-ef19.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-dynamic-multi-ef19-slides.pdf","poster":"https://grc.iit.edu/papers/2020/devarajan-2020-dynamic-multi-ef19-poster.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020bridgingstorage","slug":"kougkas-2020-bridging-storage-5e1c","title":"Bridging Storage Semantics using Data Labels and Asynchronous I/O","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"ACM Transactions on Storage (TOS\'20), Vol 16, No 4, Article 22, Nov. 2020","type":"Journal","entryType":"article","date":"November, 2020","year":2020,"era":"iit","month":11,"doi":"10.1145/3415579","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting requirements. Further, new hardware technologies and system designs create a hierarchical composition that may be ideal for computational storage operations. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elasticity, and promotes in-situ analytics and software defined storage support via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"lede":"Further, new hardware technologies and system designs create a hierarchical composition that may be ideal for computational storage operations.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-bridging-storage-5e1c.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"logan2020quantifyingoverheads","slug":"logan-2020-quantifying-overheads-cfc2","title":"Quantifying the Overheads of the Modern Linux I/O Stack","authors":["L. Logan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/logan-2020-quantifying-overheads-cfc2.pdf","poster":"https://grc.iit.edu/papers/2020/logan-2020-quantifying-overheads-cfc2-poster.pdf"},"tags":["I/O Bottleneck","Filesystems","Linux"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2020characterizingapproximating","slug":"rajesh-2020-characterizing-approximating-1de1","title":"Characterizing and Approximating I/O Behavior of HDF5 Applications","authors":["N. Rajesh","G. Heber","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/rajesh-2020-characterizing-approximating-1de1.pdf","poster":"https://grc.iit.edu/papers/2020/rajesh-2020-characterizing-approximating-1de1-poster.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020chronolog","slug":"kougkas-2020-chronolog-c458","title":"ChronoLog: A Distributed Shared Tiered Log Store with Time-based Data Ordering","authors":["A. Kougkas","H. Devarajan","K. Bateman","J. Cernuda","N. Rajesh","X.-H. Sun"],"venue":"The 36th International Conference on Massive Storage Systems and Technology (MSST\'20), Oct. 29-30, 2020","type":"Conference","entryType":"inproceedings","date":"October, 2020","year":2020,"era":"iit","month":10,"abstract":"Modern applications produce and process massive amounts of activity (or log) data. Traditional storage systems were not designed with an append-only data model and a new storage abstraction aims to fill this gap: the distributed shared log store. However, existing solutions struggle to provide a scalable, parallel, and high-performance solution that can support a diverse set of conflicting log workload requirements. Finding the tail of a distributed log is a centralized point of contention. In this paper, we show how using physical time can help alleviate the need of centralized synchronization points. We present ChronoLog, a new, distributed, shared, and multi-tiered log store that can handle more than a million tail operations per second. Evaluation results show ChronoLog\'s potential, outperforming existing solution by an order of magnitude.","hasAbstract":true,"lede":"We show how using physical time can help alleviate the need of centralized synchronization points.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-chronolog-c458.pdf"},"tags":["Distributed Log","Shared Log","Tiered Storage","ChronoLog"],"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hcl","slug":"devarajan-2020-hcl-d2f4","title":"HCL: Distributing Parallel Data Structures in Extreme Scales","authors":["H. Devarajan","A. Kougkas","K. Bateman","X.-H. Sun"],"venue":"IEEE International Conference on Cluster Computing (CLUSTER\'20), Sept. 14-17, 2020","type":"Conference","entryType":"inproceedings","date":"September, 2020","year":2020,"era":"iit","month":9,"doi":"10.1109/cluster49012.2020.00035","abstract":"Most parallel programs use irregular control flow and data structures, which are perfect for one-sided communication paradigms such as MPI or PGAS programming languages. However, these environments lack the presence of efficient function-based application libraries that can utilize popular communication fabrics such as TCP, Infinity Band (IB), and RDMA over Converged Ethernet (RoCE). Additionally, there is a lack of high-performance data structure interfaces. We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues. HCL uses a RPC over RDMA technology that implements a novel procedural programming paradigm. In this paper, we argue a RPC over RDMA technology can serve as a high-performance, flexible, and co-ordination free backend for implementing complex data structures. Evaluation results from testing real workloads shows that HCL programs are 2x to 12x faster compared to BCL, a state-of-the-art distributed data structure library.","hasAbstract":true,"lede":"We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4-slides.pdf"},"tags":["Distributed Data Structure","RPC over RDMA","Hybrid Data Access Model","HPC Data Containers","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hcompress","slug":"devarajan-2020-hcompress-70f7","title":"HCompress: Hierarchical Data Compression for Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","L. Logan","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00064","abstract":"Modern scientific applications read and write massive amounts of data through simulations, observations, and analysis. These applications spend the majority of their runtime in performing I/O. HPC storage solutions include fast node-local and shared storage resources to elevate applications from this bottleneck. Moreover, several middleware libraries (e.g., Hermes) are proposed to move data between these tiers transparently. Data reduction is another technique that reduces the amount of data produced and, hence, improve I/O performance. These two technologies, if used together, can benefit from each other. The effectiveness of data compression can be enhanced by selecting different compression algorithms according to the characteristics of the different tiers, and the multi-tiered hierarchy can benefit from extra capacity. In this paper, we design and implement HCompress, a hierarchical data compression library that can improve the application\'s performance by harmoniously leveraging both multi-tiered storage and data compression. We have developed a novel compression selection algorithm that facilitates the optimal matching of compression libraries to the tiered storage. Our evaluation shows that HCompress can improve scientific application\'s performance by 7x when compared to other state-of-the-art tiered storage solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Compression","Data-Reduction","Dynamic Choice","Workflow Priorities","Library","Middleware","Engine","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hfetch","slug":"devarajan-2020-hfetch-46e9","title":"HFetch: Hierarchical Data Prefetching for Scientific Workflows in Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00017","abstract":"In the era of data-intensive computing, accessing data with a high-throughput and low-latency is more imperative than ever. Data prefetching is a well-known technique for hiding read latency. However, existing solutions do not consider the new deep memory and storage hierarchy and also suffer from under-utilization of prefetching resources and unnecessary evictions. Additionally, existing approaches implement a client- pull model where understanding the application\'s I/O behavior drives prefetching decisions. Moving towards exascale, where machines run multiple applications concurrently by accessing files in a workflow, a more data-centric approach can resolve challenges such as cache pollution and redundancy. In this study, we present HFetch, a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching. We demonstrate the benefits of such an approach. Results show 10- 35% performance gains over existing prefetchers and over 50% when compared to systems with no prefetching.","hasAbstract":true,"lede":"In this study, we present HFetch, a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hfetch-46e9.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hfetch-46e9-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Prefetching","Data-Fetching","Dynamic Choice","Data-Centric","Library","Middleware","Engine","Data-Aware","Workflow-Aware","Server-Push","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020ioacceleration","slug":"kougkas-2020-io-acceleration-4458","title":"I/O Acceleration via Multi-Tiered Data Buffering and Prefetching","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"Journal of Computer Science and Technology (JCST\'20), vol 35. no 1. pp 92-120","type":"Journal","entryType":"article","date":"January, 2020","year":2020,"era":"iit","month":1,"doi":"10.1007/s11390-020-9781-1","abstract":"Modern High-Performance Computing (HPC) systems are adding extra layers to the memory and storage hierarchy, named deep memory and storage hierarchy (DMSH), to increase I/O performance. New hardware technologies, such as NVMe and SSD, have been introduced in burst buffer installations to reduce the pressure for external storage and boost the burstiness of modern I/O systems. The DMSH has demonstrated its strength and potential in practice. However, each layer of DMSH is an independent heterogeneous system and data movement among more layers is significantly more complex even without considering heterogeneity. How to efficiently utilize the DMSH is a subject of research facing the HPC community. Further, accessing data with a high-throughput and low-latency is more imperative than ever. Data prefetching is a well-known technique for hiding read latency by requesting data before it is needed to move it from a high-latency medium (e.g., disk) to a low-latency one (e.g., main memory). However, existing solutions do not consider the new deep memory and storage hierarchy and also suffer from under-utilization of prefetching resources and unnecessary evictions. Additionally, existing approaches implement a client-pull model where understanding the application\'s I/O behavior drives prefetching decisions. Moving towards exascale, where machines run multiple applications concurrently by accessing files in a workflow, a more data-centric approach resolves challenges such as cache pollution and redundancy. In this paper, we present the design and implementation of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system. Hermes enables, manages, supervises, and, in some sense, extends I/O buffering to fully integrate into the DMSH. We introduce three novel data placement policies to efficiently utilize all layers and we present three novel techniques to perform memory, metadata, and communication management in hierarchical buffering systems. Additionally, we demonstrate the benefits of a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching. Our evaluation shows that, in addition to automatic data movement through the hierarchy, Hermes can significantly accelerate I/O and outperforms by more than 2x state-of-the-art buffering platforms. Lastly, results show 10%-35% performance gains over existing prefetchers and over 50% when compared to systems with no prefetching.","hasAbstract":true,"lede":"We present the design and implementation of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-io-acceleration-4458.pdf"},"tags":["I/O Buffering","Heterogeneous Buffering","Layered Buffering","Deep Memory Hierarchy","Burst Buffers","Hierarchical Data Prefetching","Data-Centric Architecture","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"feng2019niobe","slug":"feng-2019-niobe-19f9","title":"NIOBE: An Intelligent I/O Bridging Engine for Complex and Distributed Workflows","authors":["K. Feng","H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The 7th IEEE International Conference on Big Data, 2019. pp. 493-502","type":"Conference","entryType":"inproceedings","date":"December, 2019","year":2019,"era":"iit","month":12,"doi":"10.1109/bigdata47090.2019.9006363","abstract":"In the age of data-driven computing, integrating High Performance Computing (HPC) and Big Data (BD) en- vironments may be the key to increasing productivity and to driving scientific discovery forward. Scientific workflows consist of diverse applications (i.e., HPC simulations and BD analysis) each with distinct representations of data that introduce a se- mantic barrier between the two environments. To solve scientific problems at scale, accessing semantically different data from different storage resources is the biggest unsolved challenge. In this work, we aim to address a critical question: \\"How can we exploit the existing resources and efficiently provide transparent access to data from/to both environments\\". We propose iNtelligent I/O Bridging Engine (NIOBE), a new data integration framework that enables integrated data access for scientific workflows with asynchronous I/O and data aggregation. NIOBE performs the data integration using available I/O resources, in contrast to existing optimizations that ignore the I/O nodes present on the data path. In NIOBE, data access is optimized to consider both the ongoing production and the consumption of the data in the future. Experimental results show that with NIOBE, an integrated scientific workflow can be accelerated by up to 10x when compared to a no-integration baseline and by up to 133% compared to other state-of-the-art integration solutions.","hasAbstract":true,"lede":"We aim to address a critical question: \\"How can we exploit the existing resources and efficiently provide transparent access to data from/to both environments\\".","links":{"pdf":"https://grc.iit.edu/papers/2019/feng-2019-niobe-19f9.pdf"},"tags":["Data Integration","Integrated Workflow","Data Aggregation","KVS","Parallel File System (PFS)"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2019efficientdata","slug":"cernuda-2019-efficient-data-b08d","title":"Efficient Data Eviction across Multiple Tiers of Storage","authors":["J. Cernuda","H. Trivino","H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'19)","type":"Poster","entryType":"misc","date":"November, 2019","year":2019,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2019/cernuda-2019-efficient-data-b08d.pdf","poster":"https://grc.iit.edu/papers/2019/cernuda-2019-efficient-data-b08d-poster.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2019hfetch","slug":"devarajan-2019-hfetch-980e","title":"HFetch: Hierarchical Data Prefetching in Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'19) Best Poster Nominee, Ph.D Forum","type":"Poster","entryType":"misc","date":"November, 2019","year":2019,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2019/devarajan-2019-hfetch-980e.pdf","slides":"https://grc.iit.edu/papers/2019/devarajan-2019-hfetch-980e-slides.pdf","poster":"https://grc.iit.edu/papers/2019/devarajan-2019-hfetch-980e-poster.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Prefetching","Server-Centric","Data-Centric","File Scoring","Data Scoring","Workflow-Aware","Lightweight","Server-Side","Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2019labios","slug":"kougkas-2019-labios-8411","title":"LABIOS: A Distributed Label-Based I/O System","authors":["A. Kougkas","H. Devarajan","J. Lofstead","X.-H. Sun"],"venue":"The 28th International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'19), Phoenix, USA 2019. pp. 13-24. Karsten Schwan Best Paper Award","type":"Conference","entryType":"inproceedings","date":"June, 2019","year":2019,"era":"iit","month":6,"doi":"10.1145/3307681.3325405","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting re- quirements. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elastic- ity, and promotes in-situ analytics via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411.pdf","slides":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411-slides.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage","Hermes"],"_projectIds":["hermes","labios"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"CCF-1744317","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true},{"agency":"NSF","award":"CNS-1526887","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"grcAwards":"Karsten Schwan Best Paper Award","status":"published","visibility":"public"},{"citeKey":"devarajan2019intelligent","slug":"devarajan-2019-intelligent--e9fd","title":"An Intelligent, Adaptive, and Flexible Data Compression Framework","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"IEEE/ACM International Symposium in Cluster, Cloud, and Grid Computing (CCGrid\'19), Larnaca, Cyprus2019. pp. 82-91.","type":"Conference","entryType":"inproceedings","date":"May, 2019","year":2019,"era":"iit","month":5,"doi":"10.1109/ccgrid.2019.00019","abstract":"The data explosion phenomenon in modern appli- cations causes tremendous stress on storage systems. Developers use data compression, a size-reduction technique, to address this issue. However, each compression library exhibits different strengths and weaknesses when considering the input data type and format. We present Ares, an intelligent, adaptive, and flexible compression framework which can dynamically choose a compression library for a given input data based on the type of the workload and provides an appropriate infrastructure to users to fine-tune the chosen library. Ares is a modular framework which unifies several compression libraries while allowing the addition of more compression libraries by the user. Ares is a unified compression engine that abstracts the complexity of using different compression libraries for each workload. Evaluation results show that under real-world applications, from both scientific and Cloud domains, Ares performed 2-6x faster than competitive solutions with a low cost of additional data analysis (i.e., overheads around 10%) and up to 10x faster against a baseline of no compression at all.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/devarajan-2019-intelligent--e9fd.pdf","slides":"https://grc.iit.edu/papers/2019/devarajan-2019-intelligent--e9fd-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"CCF-1744317","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true},{"agency":"NSF","award":"CNS-1526887","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2018vidya","slug":"devarajan-2018-vidya-e65b","title":"Vidya: Performing Code-Block I/O Characterization for Data Access Optimization","authors":["H. Devarajan","A. Kougkas","P. Challa","X.-H. Sun"],"venue":"The IEEE International Conference on High Performance Computing, Data, and Analytics 2018 (HiPC\'18), Bengaluru, India2018. pp. 255-264.","type":"Conference","entryType":"inproceedings","date":"December, 2018","year":2018,"era":"iit","month":12,"doi":"10.1109/hipc.2018.00036","abstract":"Understanding, characterizing and tuning scientific applications\' I/O behavior is an increasingly complicated process in HPC systems. Existing tools use either offline profiling or online analysis to get insights into the applications\' I/O patterns. However, there is lack of a clear formula to characterize applica- tions\' I/O. Moreover, these tools are application specific and do not account for multi-tenant systems. This paper presents Vidya, an I/O profiling framework which can predict application\'s I/O intensity using a new formula called Code-Block I/O Character- ization (CIOC). Using CIOC, developers and system architects can tune an application\'s I/O behavior and better match the underlying storage system to maximize performance. Evaluation results show that Vidya can predict an application\'s I/O intensity with a variance of 0.05%. Vidya can profile applications with a high accuracy of 98% while reducing profiling time by 9x. We further show how Vidya can optimize an application\'s I/O time by 3.7x.","hasAbstract":true,"lede":"This paper presents Vidya, an I/O profiling framework which can predict application\'s I/O intensity using a new formula called Code-Block I/O Character- ization (CIOC).","links":{"pdf":"https://grc.iit.edu/papers/2018/devarajan-2018-vidya-e65b.pdf","slides":"https://grc.iit.edu/papers/2018/devarajan-2018-vidya-e65b-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2018harmonia","slug":"kougkas-2018-harmonia-5ca9","title":"Harmonia: An Interference-Aware Dynamic I/O Scheduler for Shared Non-Volatile Burst Buffers","authors":["A. Kougkas","H. Devarajan","X.-H. Sun","J. Lofstead"],"venue":"The IEEE International Conference on Cluster Computing 2018 (Cluster\'18), Belfast, UK2018. pp. 290-301.","type":"Conference","entryType":"inproceedings","date":"September, 2018","year":2018,"era":"iit","month":9,"doi":"10.1109/cluster.2018.00046","abstract":"Modern HPC systems employ burst buffer installations to reduce the peak I/O requirements for external storage and deal with the burstiness of I/O in modern scientific applications. These I/O buffering resources are shared between multiple applications that run concurrently. This leads to severe performance degradation due to contention, a phenomenon called cross-application I/O interference. In this paper, we first explore the negative effects of interference at the burst buffer layer and we present two new metrics that can quantitatively describe the slowdown applications experience due to interference. We introduce Harmonia, a new dynamic I/O scheduler that is aware of interference, adapts to the underlying system, implements a new 2-way decision-making process and employs several scheduling policies to maximize the system efficiency and applications\' performance. Our evaluation shows that Harmonia, through better I/O scheduling, can outperform by 3x existing state-of-the-art buffering management solutions and can lead to better resource utilization.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-harmonia-5ca9.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-harmonia-5ca9-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2018hermes","slug":"kougkas-2018-hermes-25f4","title":"Hermes: A Heterogeneous-Aware Multi-Tiered Distributed I/O Buffering System","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The 27th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC), Tempe, AZ, USA, 2018. pp. 219-230","type":"Conference","entryType":"inproceedings","date":"June, 2018","year":2018,"era":"iit","month":6,"doi":"10.1145/3208040.3208059","abstract":"Modern High-Performance Computing (HPC) systems are adding extra layers to the memory and storage hierarchy, named deep memory and storage hierarchy (DMSH), to increase I/O perfor- mance. New hardware technologies, such as NVMe and SSD, have been introduced in burst buffer installations to reduce the pressure for external storage and boost the burstiness of modern I/O systems. The DMSH has demonstrated its strength and potential in practice. However, each layer of DMSH is an independent heterogeneous system and data movement among more layers is significantly more complex even without considering heterogeneity. How to efficiently utilize the DMSH is a subject of research facing the HPC community. In this paper, we present the design and implementa- tion of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system. Hermes enables, manages, su- pervises, and, in some sense, extends I/O buffering to fully integrate into the DMSH. We introduce three novel data placement policies to efficiently utilize all layers and we present three novel techniques to perform memory, metadata, and communication management in hierarchical buffering systems. Our evaluation shows that, in ad- dition to automatic data movement through the hierarchy, Hermes can significantly accelerate I/O and outperforms by more than 2x state-of-the-art buffering platforms.","hasAbstract":true,"lede":"We present the design and implementa- tion of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system.","links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-hermes-25f4.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-hermes-25f4-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2018iris","slug":"kougkas-2018-iris-f1a6","title":"IRIS: I/O Redirection via Integrated Storage","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The 32nd ACM International Conference on Supercomputing (ICS), Bejing, China2018. pp. 33-42.","type":"Conference","entryType":"inproceedings","date":"June, 2018","year":2018,"era":"iit","month":6,"doi":"10.1145/3205289.3205322","abstract":"There is an ocean of available storage solutions in modern high-performance and distributed systems. These solutions consist of Par- allel File Systems (PFS) for the more traditional high-performance computing (HPC) systems and of Object Stores for emerging cloud environments. More often than not, these storage solutions are tied to specific APIs and data models and thus, bind developers, applications, and entire computing facilities to using certain inter-faces. Each storage system is designed and optimized for certain applications but does not perform well for others. Furthermore, modern applications have become more and more complex consist- ing of a collection of phases with different computation and I/O requirements. In this paper, we propose a unified storage access system, called IRIS (i.e., I/O Redirection via Integrated Storage). IRIS enables unified data access and seamlessly bridges the semantic gap between file systems and object stores. With IRIS, emerging High-Performance Data Analytics software has capable and diverse I/O support. IRIS can bring us closer to the convergence of HPC and Cloud environments by combining the best storage subsystems from both worlds. Experimental results show that IRIS can grant more than 7x improvement in performance than existing solutions.","hasAbstract":true,"lede":"We propose a unified storage access system, called IRIS (i.e., I/O Redirection via Integrated Storage).","links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-iris-f1a6.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-iris-f1a6-slides.pdf"},"_projectIds":["iris"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2017openethernet","slug":"devarajan-2017-open-ethernet-e0f1","title":"Open Ethernet Drive: Evolution of Energy-Ef\ufb01cient Storage Technology","authors":["H. Devarajan","A. Kougkas","X.-H. Sun","H. Che"],"venue":"The ACM SIGHPC 8th International Workshop on Data-Intensive Computing in the Clouds (DataCloud 2017), in conjunction with SC\'17, Denver, CO, USAvol. 17","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"abstract":"An Open Ethernet Drive, also known as an OED, is a new technology that embeds a low-powered processor, a fixed-size memory and an Ethernet card on a disk drive (e.g. HDD or SSD). All major storage vendors have introduced their respective implementations with similar architectural designs. As the technology progresses into its second generation, the perfor- mance characteristics have improved substantially. In this study, we first demonstrate the differences between two generations of the OED technology. We run a variety of benchmarks and applications to thoroughly evaluate the performance of this device and its compatibility with the current ecosystem. Furthermore, we investigate the performance and energy footprint of the OED technology when used as a storage server and as an I/O accelerator. Evaluation results show that OED technology can be a reliable, scalable, energy and cost efficient storage solution. It is a viable replacement for storage servers offering competitive performance while consuming only 10% of the power that a typ- ical storage node needs. Finally, this study shows that OED\'s can be used as I/O accelerators capable of executing data-intensive computations (such as sorting, compression/decompression, etc.) on local data, whereby the expensive data movement is minimized resulting in low power consumption.","hasAbstract":true,"lede":"An Open Ethernet Drive, also known as an OED, is a new technology that embeds a low-powered processor, a fixed-size memory and an Ethernet card on a disk drive (e.g.","links":{"pdf":"https://grc.iit.edu/papers/2017/devarajan-2017-open-ethernet-e0f1.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2017enosis","slug":"kougkas-2017-enosis-ea06","title":"Enosis: Bridging the Semantic Gap between File-based and Object-based Data Models","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The ACM SIGHPC 8th International Workshop on Data-Intensive Computing in the Clouds (DataCloud 2017), in conjunction with SC\'17, Denver, CO, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"abstract":"File and block storage are well-defined concepts in computing and have been used as common components of computer systems for decades. Big data has led to new types of storage. The predominant data model in cloud storage is the object-based storage and it is highly successful. Object stores follow a simpler API with get() and put() operations to interact with the data. A wide variety of data analysis software have been developed around objects using their APIs. However, object storage and traditional file storage are designed for different purpose and for different applications. Organizations maintain file-based storage clusters and a high volume of existing data are stored in files. Moreover, many new applications need to access data from both types of storage. In this paper, we first explore the key differences between object-based and the more traditional file-based storage systems. We have designed and implemented several file-to-object mapping algorithms to bridge the semantic gap between these data models. Our evaluation shows that by achieving an efficient such mapping, our library can grant 2x- 27x higher performance against a naive one-to-one mapping and with minimal overheads. Our study exposes various strengths and weaknesses of each mapping strategy and frames the extended potential of a unified data access system.","hasAbstract":true,"lede":"We first explore the key differences between object-based and the more traditional file-based storage systems.","links":{"pdf":"https://grc.iit.edu/papers/2017/kougkas-2017-enosis-ea06.pdf","slides":"https://grc.iit.edu/papers/2017/kougkas-2017-enosis-ea06-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2017syndesis","slug":"kougkas-2017-syndesis-d59c","title":"Syndesis: Mapping Objects to Files for a Unified Data Access System","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The ACM SIGHPC 8th International Workshop on Many-Task Computing on Clouds, Grids, and Supercomputers (MTAGS 2017), in conjunction with SC\'17, Denver, CO, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"abstract":"The predominant data model in cloud storage is the object-based storage. Object stores follow a simpler API with get() and put() operations to interact with the data. A wide variety of data analysis software has been developed around objects using their APIs. In fact, the evolution of Big Data analytics is a major driver for highly optimized data-centric quality software. However, organizations maintain file-based storage clusters and a high volume of existing data are stored in files. This is specifically true for the scientific communities. In this paper, we present the key characteristics of object-based and file-based storage APIs, we explore several object-to-file mappings aiming to bridge the semantic gap between these data models. The evaluation of our mapping algorithms exposes various strengths and weaknesses of each strategy and frames the extended potential of a unified data access system. Results show that our solution can offer more than 3x higher performance for specific workloads while keeping minimal overhead of our library.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2017/kougkas-2017-syndesis-d59c.pdf","slides":"https://grc.iit.edu/papers/2017/kougkas-2017-syndesis-d59c-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2017rethinkingkey","slug":"kougkas-2017-rethinking-key-02de","title":"Rethinking Key Value Store for Parallel I/O Optimization","authors":["A. Kougkas","H. Eslami","R. Thakur","W. D. Gropp","X.-H. Sun"],"venue":"International Journal of High Performance Applications,2017. vol. 31, no. 4, pp. 335-356","type":"Journal","entryType":"article","date":"July, 2017","year":2017,"era":"iit","month":7,"doi":"10.1177/1094342016677084","abstract":"Key-value stores are being widely used as the storage system for large-scale internet services and cloud storage systems. However, they are rarely used in HPC systems, where parallel file systems are the dominant storage solution. In this study, we examine the architecture differences and performance characteristics of parallel file systems and key-value stores. We propose using key-value stores to optimize overall Input/Output (I/O) performance, especially for workloads that parallel file systems cannot handle well, such as the cases with intense data synchronization or heavy metadata oper- ations. We conducted experiments with several synthetic benchmarks, an I/O benchmark, and a real application. We modeled the performance of these two systems using collected data from our experiments, and we provide a predictive method to identify which system offers better I/O performance given a specific workload. The results show that we can optimize the I/O performance in HPC systems by utilizing key-value stores.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2017/kougkas-2017-rethinking-key-02de.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2016leveragingburst","slug":"kougkas-2016-leveraging-burst-85be","title":"Leveraging Burst Buffer Coordination to Prevent I/O Interference","authors":["A. Kougkas","M. Dorier","R. Latham","R. Ross","X.-H. Sun"],"venue":"The eScience\'16, Baltimore, Maryland, USA2016, pp. 371-380","type":"Conference","entryType":"inproceedings","date":"October, 2016","year":2016,"era":"iit","month":10,"doi":"10.1109/escience.2016.7870922","abstract":"Concurrent accesses to the shared storage resources in current HPC machines lead to severe performance degradation caused by I/O contention. In this study, we identify some key challenges to efficiently handling interleaved data accesses, and we propose a system-wide solution to optimize global performance. We implemented and tested several I/O scheduling policies, including prioritizing specific applications by leveraging burst buffers to defer the conflicting accesses from another application and/or directing the requests to different storage servers inside the parallel file system infrastructure. The results show that we mitigate the negative effects of interference and optimize the performance up to 2x depending on the selected I/O policy.","hasAbstract":true,"lede":"In this study, we identify some key challenges to efficiently handling interleaved data accesses, and we propose a system-wide solution to optimize global performance.","links":{"pdf":"https://grc.iit.edu/papers/2016/kougkas-2016-leveraging-burst-85be.pdf","slides":"https://grc.iit.edu/papers/2016/kougkas-2016-leveraging-burst-85be-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2016towardsenergy","slug":"kougkas-2016-towards-energy-6062","title":"Towards Energy Efficient Data Management in HPC: The Open Ethernet Drive Approach","authors":["A. Kougkas","A. Fleck","X.-H. Sun"],"venue":"PDSW-DISCS\'16, in conjunction with SC\'16","type":"Workshop","entryType":"inproceedings","date":"January, 2016","year":2016,"era":"iit","month":1,"doi":"10.1109/pdsw-discs.2016.012","abstract":"An Open Ethernet Drive (OED) is a new technology that encloses into a hard drive (HDD or SSD) a low-power processor, a fixed-size memory and an Ethernet card. In this study, we thoroughly evaluate the performance of such device and the energy requirements to operate it. The results show that first it is a viable solution to offload data-intensive computations on the OED while maintaining a reasonable performance, and second, the energy consumption savings from utilizing such technology are significant as it only consumes 10% of the power needed by a normal server node. We propose that by using OED devices as storage servers in HPC, we can run a reliable, scalable, cost and energy efficient storage solution.","hasAbstract":true,"lede":"We propose that by using OED devices as storage servers in HPC, we can run a reliable, scalable, cost and energy efficient storage solution.","links":{"pdf":"https://grc.iit.edu/papers/2016/kougkas-2016-towards-energy-6062.pdf","slides":"https://grc.iit.edu/papers/2016/kougkas-2016-towards-energy-6062-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"eslami2015efficientdisk","slug":"eslami-2015-efficient-disk-fda9","title":"Efficient Disk-to-Disk Sorting: A Case Study in Decoupled Execution Paradigm","authors":["H. Eslami","A. Kougkas","M. Kotsifakou","T. Kasampalis","K. Feng","Y. Lu","W. D. Gropp","X.-H. Sun","Y. Chen","R. Thakur"],"venue":"Data Intensive Scalable Computing Systems Workshop (DISCS), in conjunction with ACM/IEEE SuperComputing 2015, Austin, TX, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2015","year":2015,"era":"iit","month":11,"doi":"10.1145/2831244.2831249","hasAbstract":false,"links":{"pdf":"https://dl.acm.org/ft_gateway.cfm?ftid=1643727&id=2831249"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"he2015heterogeneityaware","slug":"he-2015-heterogeneity-aware-d995","title":"A Heterogeneity-Aware Region-Level Data Layout Scheme for Hybrid Parallel File Systems","authors":["S. He","X.-H. Sun","Y. Wang","A. Kougkas","A. Haider"],"venue":"44th International Conference on Parallel Processing (ICPP\'15), Beijing, China","type":"Conference","entryType":"inproceedings","date":"September, 2015","year":2015,"era":"iit","month":9,"doi":"10.1109/icpp.2015.43","abstract":"Parallel file systems (PFS) are commonly used in high-end computing systems. With the emergence of solid state drives (SSD), hybrid PFSs, which consist of both HDD and SSD servers, provide a practical I/O system solution for data-intensive applications. However, most existing PFS layout schemes are inefficient for hybrid PFSs due to their lack of awareness of the performance differences between heterogeneous servers and the workload changes between different parts of a file. This lack of recognition can result in severe I/O performance degradation. In this study, we propose a heterogeneity-aware region-level (HARL) data layout scheme to improve the data distribution of a hybrid PFS. HARL first divides a file into fine-grained, varying sized regions according to the changes of an application\'s I/O work- load, then chooses appropriate file stripe sizes on heterogeneous servers based on the server performance for each file region. Experimental results of representative benchmarks show that HARL can greatly improve the I/O system performance.","hasAbstract":true,"lede":"In this study, we propose a heterogeneity-aware region-level (HARL) data layout scheme to improve the data distribution of a hybrid PFS.","links":{"pdf":"https://grc.iit.edu/papers/2015/he-2015-heterogeneity-aware-d995.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yin2014rethinkingkey","slug":"yin-2014-rethinking-key-484a","title":"Rethinking Key-Value Store for Parallel I/O Optimization","authors":["Y. Yin","A. Kougkas","K. Feng","H. Eslami","Y. Lu","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"Data Intensive Scalable Computing Systems Workshop (DISCS), in conjunction with ACM/IEEE SuperComputing 2014, New Orleans, LA, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2014","year":2014,"era":"iit","month":11,"doi":"10.1109/discs.2014.11","abstract":"Key-Value Stores (KVStore) are being widely used as the storage system for large-scale Internet services and cloud storage systems. However, they are rarely used in HPC systems, where parallel file systems (PFS) are the dominant storage systems. In this study, we carefully examine the architecture difference and performance characteristics of PFS and KVStore. We propose that it is valuable to utilize KVStore to optimize the overall I/O performance, especially for the workloads that PFS cannot handle well, such as the cases with hurtful data synchronization or heavy metadata operations. To verify this proposal, we conducted comprehensive experiments with several synthetic benchmarks, an I/O benchmark, and a real application. The results show that our proposal is promising.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2014/yin-2014-rethinking-key-484a.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);